    reg [15:0] det_mask;
    reg [4:0]  det_cnt;
    reg        pre_rt;
    reg        pv;

    initial inv_flag = 16'd0;
    initial det_mask = 16'd0;
    initial det_cnt  = 5'd0;
    initial locked   = 1'b0;
    initial pre_rt   = 1'b1;
    initial pv       = 1'b0;

    reg [15:0] new_mask;
    reg [15:0] nxt_inv;
    reg [4:0]  new_cnt;
    integer i;

    always @(*) begin
        new_mask = 16'd0;
        nxt_inv  = inv_flag;
        new_cnt  = 5'd0;
        for (i = 0; i < 16; i = i + 1) begin
            if (!det_mask[i]) begin
                if (rx_data[8*i +: 8] == TS) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b0;
                end else if (rx_data[8*i +: 8] == TS_INV) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b1;
                end
            end
            new_cnt = new_cnt + {4'd0, new_mask[i]};
        end
    end

    wire [4:0] sum_cnt = det_cnt + new_cnt;

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : g_lane
            assign data_out[8*g +: 8] = rx_data[8*g +: 8] ^ {8{inv_flag[g]}};
        end
    endgenerate

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            inv_flag <= 16'd0;
            det_mask <= 16'd0;
            det_cnt  <= 5'd0;
            locked   <= 1'b0;
            pre_rt   <= 1'b1;
        end else if (en) begin
            if (retrain) begin
                inv_flag <= 16'd0;
                det_mask <= 16'd0;
                det_cnt  <= 5'd0;
                locked   <= 1'b0;
                pre_rt   <= 1'b0;
