module wwdg_window (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       stop,
    input  wire       kick,
    input  wire [7:0] cfg_reload,
    input  wire [7:0] cfg_win,
    output wire [1:0] o_fault,
    output wire       o_armed,
    output wire [7:0] o_cnt
);
    reg       pv       = 1'b0;
    reg       armed    = 1'b0;
    reg [7:0] cnt      = 8'd64;
    reg [7:0] reload   = 8'd64;
    reg [7:0] win_thr  = 8'd0;
    reg [1:0] fault    = 2'b00;
    reg       win_open = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (start) begin
            armed    <= 1'b1;
            reload   <= cfg_reload | 8'h40;
            win_thr  <= cfg_win & 8'h3F;
            cnt      <= cfg_reload | 8'h40;
            fault    <= 2'b00;
            win_open <= 1'b0;
        end else if (stop) begin
            armed <= 1'b0;
        end else if (armed && ce && fault == 2'b00) begin
            if (kick) begin
                if (cnt > win_thr)
                    fault[0] <= 1'b1;
                else begin
                    cnt      <= reload;
                    win_open <= 1'b0;
                end
            end else if (cnt == 8'd0) begin
                fault[1] <= 1'b1;
            end else begin
                cnt      <= cnt - 8'd1;
                win_open <= ((cnt - 8'd1) <= win_thr);
            end
        end
    end

    assign o_fault = fault;
    assign o_armed = armed;
    assign o_cnt   = cnt;

    always @(posedge clk)
        if (pv && armed && $rose(fault[1]))
            assert (win_open);
endmodule


