module seg_rot_shifter #(
    parameter W = 32,
    parameter SEGS = 4
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [W-1:0]      in_data,
    input  wire [31:0]       in_amt,
    input  wire              step,
    output reg               out_valid,
    input  wire              out_ready,
    output wire [SEGS*W-1:0] out_data
);
    reg [SEGS*W-1:0] segs;
    reg [SEGS-1:0]   spill;
    reg              par;
    reg              busy;
    reg [31:0]       cnt;

    initial segs = {SEGS*W{1'b0}};
    initial spill = {SEGS{1'b0}};
    initial par = 1'b0;
    initial busy = 1'b0;
    initial cnt = 32'd0;
    initial out_valid = 1'b0;

    assign in_ready = !busy && !out_valid;
    assign out_data = segs;

    reg [SEGS*W-1:0] seg_nxt;
    reg [SEGS-1:0]   sp_nxt;
    integer i;
    always @(*) begin
        for (i = 0; i < SEGS; i = i + 1) begin
            seg_nxt[i*W +: W] = {segs[i*W +: (W-1)], spill[(i+SEGS-1)%SEGS]};
            sp_nxt[i] = segs[i*W + W - 2];
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            segs <= {SEGS*W{1'b0}};
            spill <= {SEGS{1'b0}};
            par <= 1'b0;
            busy <= 1'b0;
            cnt <= 32'd0;
            out_valid <= 1'b0;
        end else begin
            if (in_valid && in_ready) begin
                segs <= {{((SEGS-1)*W){1'b0}}, in_data};
                spill <= {{(SEGS-1){1'b0}}, in_data[W-1]};
                par <= ^in_data;
                cnt <= in_amt;
                busy <= 1'b1;
            end else if (busy && step) begin
                if (cnt == 32'd0) begin
                    busy <= 1'b0;
                    out_valid <= 1'b1;
                end else begin
                    segs <= seg_nxt;
                    spill <= sp_nxt;
                    cnt <= cnt - 32'd1;
                end
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    always @(posedge clk)
        if (busy) assert ((^segs) == par);
endmodule

