module frame_beat_ripple #(
    parameter W = 32,
    parameter MAX_BEATS = 12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    input  wire         s_last,
    output wire         s_ready,
    output wire         m_valid,
    input  wire         m_ready,
    output wire [W-1:0] m_count
);
    typedef enum logic [1:0] {IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0] LIMIT    = MAX_BEATS;
    localparam [W-1:0] LAST_IDX = MAX_BEATS - 1;

    state_t state;
    reg in_frame;
    reg [W-1:0] q;
    integer i;

    initial begin
        state    = IDLE;
        in_frame = 1'b0;
        q        = {W{1'b0}};
    end

    assign s_ready = (state != DONE);
    assign m_valid = (state == DONE);
    assign m_count = q;

    wire accept = s_valid && s_ready;
    wire drain  = m_valid && m_ready;

    // Ripple chain of toggle flip-flops: stage 0 toggles on each accepted
    // beat; stage g toggles when stage g-1 falls from 1 to 0 (its 'clock').
    wire [W-1:0] t;
    assign t[0] = accept;
    genvar g;
    generate
        for (g = 1; g < W; g = g + 1) begin : rip
            assign t[g] = t[g-1] & q[g-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            state    <= IDLE;
            in_frame <= 1'b0;
            q        <= {W{1'b0}};
        end else begin
            if (drain)
                q <= {W{1'b0}};
            else
                for (i = 0; i < W; i = i + 1)
                    if (t[i]) q[i] <= ~q[i];

            case (state)
                IDLE: begin
                    if (accept) begin
                        in_frame <= 1'b1;
                        state    <= (s_last || q == LAST_IDX) ? DONE : COUNTING;
                    end
                end
                COUNTING: begin
                    if (accept && (s_last || q == LAST_IDX))
                        state <= DONE;
                end
                DONE: begin
                    if (drain) begin
                        state    <= IDLE;
                        in_frame <= 1'b0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (in_frame) assert (q <= LIMIT);
endmodule

