   output wire [7:0] sig_o,
   output wire [7:0] stall_o
);
   localparam [2:0] DEPTH = 3'd4;
   localparam [4:0] LINE_LAST = 5'd23;

   reg [7:0] fifo [0:3];
   reg [1:0] wr_ptr;
   reg [1:0] rd_ptr;
   reg [2:0] cnt;
   reg [3:0] cfg_div;
   reg [3:0] cfg_hblank;
   reg       cfg_inv;
   reg [7:0] cfg_blank;
   reg [3:0] div_cnt;
   reg [3:0] hb_cnt;
   reg [4:0] col_out;
   reg [7:0] px_q;
   reg       px_vld;
   reg       px_eol;
   reg       eof_pend;
   reg [7:0] sig_run;
   reg [7:0] sig_last;
   reg [7:0] stall_cnt;

