   initial begin
       for (j = 0; j < 4; j = j + 1)
           fifo[j] = 8'h00;
   end
   initial wr_ptr = 2'd0;
   initial rd_ptr = 2'd0;
   initial cnt = 3'd0;
   initial cfg_div = 4'd0;
   initial cfg_hblank = 4'd0;
   initial cfg_inv = 1'b0;
   initial cfg_blank = 8'h00;
