    reg [63:0] l2_0 = 64'd0;
    reg [63:0] l2_1 = 64'd0;
    reg        busy = 1'b0;
    reg        ph   = 1'b0;
    reg [6:0]  sc   = 7'd0;
    reg [7:0]  cd   = 8'd0;

