        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
s1_lo <= g[1:0];
if (hi_arm)
    s1_hi <= g[3:2];
hi_arm <= lo_tc;
            s2  <= s1;
        end
    end

