        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
