module zynq_pwr_dom (
    input  wire       clk,
    input  wire       en,
    input  wire       req_on,
    input  wire       req_off,
    input  wire [6:0] idx,
    output wire       root_ready,
    output wire       busy
);
    reg [127:0] dom_on;
    reg [7:0]   refcnt;
    reg         root_on;
    reg         pend;
    reg [7:0]   prog;
    reg [7:0]   cd;
    reg         first_n;
    reg         pv;

    initial dom_on  = 128'd0;
    initial refcnt  = 8'd0;
    initial root_on = 1'b0;
    initial pend    = 1'b0;
    initial prog    = 8'd0;
    initial cd      = 8'd0;
    initial first_n = 1'b1;
    initial pv      = 1'b0;

    wire do_on  = req_on && !req_off;
    wire do_off = req_off && !req_on && !pend;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (pend) begin
                prog <= prog + 8'd1;
                cd   <= cd - 8'd1;
                if (prog == 8'd19) begin
                    pend    <= 1'b0;
                    root_on <= 1'b1;
                end
            end
            if (do_on && !dom_on[idx]) begin
                dom_on[idx] <= 1'b1;
                refcnt      <= refcnt + 8'd1;
                if (refcnt == 8'd0 && !root_on && !pend) begin
                    pend <= 1'b1;
                    prog <= 8'd0;
                    cd   <= 8'd24;
                end
            end else if (do_off && dom_on[idx]) begin
                dom_on[idx] <= 1'b0;
                refcnt      <= refcnt - 8'd1;
                if (refcnt == 8'd1 && root_on) begin
                    root_on <= 1'b0;
                    first_n <= 1'b0;
                end
            end
        end
    end

    assign root_ready = root_on;
    assign busy       = pend;

    always @(posedge clk)
        if (pv && first_n && pend && $stable(pend))
            assert ($stable(cd == 8'd0) && cd != 8'd0);
endmodule

