module flash_prog_fsm (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [7:0] i_data,
    output reg  [7:0] o_data,
    output reg        o_rd,
    output reg        o_wr,
    output reg        busy
);
    // binary-encoded programmer FSM: 5 legal encodings out of 8
    localparam [2:0] S_IDLE  = 3'd0,
                     S_LOAD  = 3'd1,
                     S_SHIFT = 3'd2,
                     S_STORE = 3'd3,
                     S_FLUSH = 3'd4;

    reg [2:0] state;
    reg [7:0] latch;

    initial state  = S_IDLE;
    initial latch  = 8'h00;
    initial o_data = 8'h00;
    initial o_rd   = 1'b0;
    initial o_wr   = 1'b0;
    initial busy   = 1'b0;   // window register: set by start, cleared at FLUSH

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    o_rd <= start;
                    o_wr <= 1'b0;
                    if (start) begin
                        state <= S_LOAD;
                        busy  <= 1'b1;
                    end
                end
                S_LOAD: begin
                    latch <= i_data;
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    state <= S_SHIFT;
                end
                S_SHIFT: begin
                    latch <= {latch[6:0], latch[7]};
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b1;
                    state <= S_STORE;
                end
                S_STORE: begin
                    o_data <= latch;
                    o_rd   <= 1'b0;
                    o_wr   <= 1'b0;
                    state  <= S_FLUSH;
                end
                S_FLUSH: begin
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    busy  <= 1'b0;
