module bcd_divider #(
    parameter DIGITS = 16
) (
    input  wire                  clk,
    input  wire                  i_clr,
    input  wire                  i_ce,
    input  wire                  i_go,
    input  wire [4*DIGITS-1:0]   i_dividend,
    input  wire [4*DIGITS-1:0]   i_divisor,
    output wire [4*DIGITS-1:0]   o_quotient,
    output wire [4*DIGITS+3:0]   o_remainder,
    output wire                  o_done
);
    localparam W  = 4*DIGITS;
    localparam RW = W + 4;
    localparam PW = $clog2(DIGITS);

    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_TABLE = 2'd1;
    localparam [1:0] P_DIV   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    function [RW-1:0] bcd_add;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] s;
        reg c;
        begin
            c = 1'b0;
            bcd_add = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                s = {1'b0, a[4*i +: 4]} + {1'b0, b[4*i +: 4]} + {4'd0, c};
                if (s > 5'd9) begin s = s + 5'd6; c = 1'b1; end
                else c = 1'b0;
                bcd_add[4*i +: 4] = s[3:0];
            end
        end
    endfunction

    function [RW-1:0] bcd_sub;
        input [RW-1:0] a;
        input [RW-1:0] b;
        integer i;
        reg [4:0] d;
        reg br;
        begin
            br = 1'b0;
            bcd_sub = {RW{1'b0}};
            for (i = 0; i < RW/4; i = i + 1) begin
                d = {1'b0, a[4*i +: 4]} - {1'b0, b[4*i +: 4]} - {4'd0, br};
                if (d[4]) begin d = d + 5'd10; br = 1'b1; end
                else br = 1'b0;
                bcd_sub[4*i +: 4] = d[3:0];
            end
        end
    endfunction

    reg [1:0]    phase      = P_IDLE;
    reg [3:0]    tbl_idx    = 4'd0;
    reg [PW-1:0] pos        = {PW{1'b0}};
    reg [W-1:0]  dvd        = {W{1'b0}};
    reg [W-1:0]  quo        = {W{1'b0}};
    reg [RW-1:0] rem        = {RW{1'b0}};
    reg [RW-1:0] acc        = {RW{1'b0}};
    reg [RW-1:0] mult [0:9];
    reg          seen_arm   = 1'b0;
    reg          seen_start = 1'b0;
    reg          done       = 1'b0;
    reg          win        = 1'b0;

    integer k;
    initial begin
        for (k = 0; k < 10; k = k + 1) mult[k] = {RW{1'b0}};
    end

    wire [RW-1:0] shifted = {rem[RW-5:0], dvd[pos*4 +: 4]};
    wire [RW-1:0] acc_sum = bcd_add(acc, mult[1]);

    reg [3:0]    qdig;
    reg [RW-1:0] qmul;
    integer j;
    always @(*) begin
        qdig = 4'd0;
        qmul = {RW{1'b0}};
        for (j = 1; j < 10; j = j + 1)
            if (shifted >= mult[j]) begin
                qdig = j;
                qmul = mult[j];
            end
    end

    wire [RW-1:0] rem_next = bcd_sub(shifted, qmul);

    always @(posedge clk) begin
        if (i_clr) begin
            phase      <= P_IDLE;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            done       <= 1'b0;
            win        <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE, P_DONE: begin
                    if (i_go) begin
                        dvd        <= i_dividend;
                        quo        <= {W{1'b0}};
                        rem        <= {RW{1'b0}};
                        mult[0]    <= {RW{1'b0}};
                        mult[1]    <= {4'd0, i_divisor};
                        acc        <= {4'd0, i_divisor};
                        tbl_idx    <= 4'd2;
                        phase      <= P_TABLE;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        done       <= 1'b0;
                        win        <= 1'b1;
                    end
                end
                P_TABLE: begin
                    for (k = 2; k < 10; k = k + 1)
                        if (tbl_idx == k) mult[k] <= acc_sum;
                    acc <= acc_sum;
                    if (tbl_idx == 4'd9) begin
                        phase      <= P_DIV;
                        seen_start <= 1'b1;
                        pos        <= DIGITS - 1;
                    end else begin
                        tbl_idx <= tbl_idx + 4'd1;
                    end
                end
                P_DIV: begin
                    rem <= rem_next;
                    quo <= {quo[W-5:0], qdig};
                    if (pos == {PW{1'b0}}) begin
                        phase <= P_DONE;
                        done  <= 1'b1;
                    end else begin
                        pos <= pos - 1'b1;
                    end
                end
                default: phase <= P_IDLE;
            endcase
        end
    end

    assign o_quotient  = quo;
    assign o_remainder = rem;
    assign o_done      = done;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(done))
            assert (seen_arm && seen_start);
endmodule

