    input  wire        rst,
    input  wire        en,
    input  wire        s_tvalid,
    input  wire        s_tuser,
    input  wire        s_tlast,
    input  wire [63:0] s_luma,
    input  wire [63:0] thr,
    input  wire [5:0]  ratio_sh,
    input  wire        eof,
    output wire        s_tready,
    output wire        m_tvalid,
    output wire        m_tuser,
    output wire        m_tlast,
    output wire [63:0] m_luma,
    output wire [63:0] o_gain,
    output wire [63:0] o_hist0,
    output wire        o_win
