module relo_belt (
    input wire clk,
    input wire rst,
    input wire en,
    input wire drop,
    input wire [63:0] din,
    input wire [4:0] rd_pos,
    input wire ckpt_open,
    input wire ckpt_close,
    output wire [63:0] dout
);
    reg [63:0] slot [0:31];
    reg [4:0] head;
    reg [63:0] drops;
    reg [63:0] win_cnt;
    reg win;
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            slot[i] = 64'd0;
        head = 5'd0;
        drops = 64'd0;
        win_cnt = 64'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 32; i = i + 1)
                slot[i] <= 64'd0;
            head <= 5'd0;
            drops <= 64'd0;
            win_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (drop) begin
                slot[head] <= din;
                head <= head + 5'd1;
                drops <= drops + 64'd1;
                if (win)
                    win_cnt <= win_cnt + 64'd1;
            end
            if (ckpt_close) begin
                win <= 1'b0;
            end else if (ckpt_open) begin
                win <= 1'b1;
                win_cnt <= 64'd0;
            end
        end
    end

    assign dout = slot[head - 5'd1 - rd_pos];

    always @(posedge clk)
        if (win && !rst)
            assert (head == drops[4:0]);
