module credit_chain_guard (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire arm_req,
    input  wire send_req,
    input  wire ret_req,
    input  wire fin_req,
    output wire o_finish,
    output wire [3:0] o_credits
);
    // Credit pool: the producer spends a credit per outstanding transfer,
    // the consumer returns it.  free credits + outstanding credits == TOTAL.
    localparam [3:0] TOTAL   = 4'd8;
    localparam [1:0] PH_IDLE = 2'd0,
                     PH_ARM  = 2'd1,
                     PH_RUN  = 2'd2,
                     PH_DONE = 2'd3;

    reg [1:0] phase;
    reg [3:0] credits;
    reg [3:0] outstanding;
    reg       start_seen;
    reg       armed;        // sticky: set the first time an arm request is taken

    initial phase       = PH_IDLE;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
    initial start_seen  = 1'b0;
    initial armed       = 1'b0;

    wire do_send = send_req && ((phase == PH_ARM) || (phase == PH_RUN)) && (credits != 4'd0);
    wire do_ret  = ret_req  && (outstanding != 4'd0);
    wire do_fin  = fin_req  && (phase == PH_RUN) && (outstanding == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            phase       <= PH_IDLE;
            credits     <= TOTAL;
            outstanding <= 4'd0;
            start_seen  <= 1'b0;
        end else if (ce) begin
            if (arm_req) begin
                if (phase == PH_IDLE)
                    phase <= PH_ARM;
            end else if (do_send) begin
                credits     <= credits - 4'd1;
                outstanding <= outstanding + 4'd1;
                start_seen  <= 1'b1;
                phase       <= PH_RUN;
            end else if (do_ret) begin
                outstanding <= outstanding - 4'd1;
                credits     <= credits + 4'd1;
            end else if (do_fin) begin
                phase <= PH_DONE;
            end
        end
    end

    // sticky arm register, never cleared once set
    always @(posedge clk)
        if (ce && arm_req)
            armed <= 1'b1;

    assign o_finish  = (phase == PH_DONE);
    assign o_credits = credits;

    // After the session has been armed: a finish can only be observed if the
    // start step really happened and every spent credit has come back.
    always @(*)
        if (armed)
            assert (!o_finish || (start_seen && (credits == TOTAL)));
endmodule

