    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       flush,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output wire       o_valid,
    output wire [7:0] o_data
);
