reg [3:0] req_prev;

   // the ledger, not vld, is the authority on lease occupancy
  wire [3:0] n_ret       = n_drop + n_drop_hi;
  wire       outstanding = (n_take != n_ret);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
n_drop = 4'd0;
       n_drop_hi = 4'd0;
stale  = 1'b0;
req_seen  = 4'd0;
req_prev  = 4'd0;
    end

