// fixed-latency (6 cycle) pipeline occupancy shift register
reg [5:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// remaining issue credits: an op is only taken while credits are left
reg [2:0] cred;
// currently programmed outstanding-op limit, retuned at each quiesce point
reg [2:0] lim;
// congestion flag: enable dropped while work was still in flight
reg       thr;
// credit-return path: a retired op's credit takes four more cycles to walk
// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;
// returned credits wait here until the credit counter's write port is free
reg [2:0] rtn;
// merge stage: a credit leaving the park register spends one cycle in this
// flop before it is written into the issue-side credit counter
reg       mrg;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;
initial rtn      = 3'd0;
initial mrg      = 1'b0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// at most one parked credit is merged back per cycle, and only on cycles
// where the issue side is not already updating the credit counter
wire drain = (rtn != 3'd0) && !accept;
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
mrg  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
mrg  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, mrg};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
mrg  <= drain;
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

