oq_busy <= v1 || sb_go;
oq_par  <= v1 ? p1 : sb_p;
oq_parh <= v1 ? p1h : sb_ph;
sb_v <= sb_acc || (sb_v && !sb_go);
if (sb_acc) begin
    sb_d <= i_data;
   sb_p  <= ^i_data[3:0];
   sb_ph <= ^i_data[7:4];
