// bin-0 posted-write ledger: samples pushed into the posted-write buffer
// versus parked writes retired into the bin-0 counter
reg [3:0] n_p0, n_w0;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
