end
        if (incr) begin
            case (i_bin)
2'd0: ; // bin-0 sample is posted into b0_pend above
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
