// plus a status readout multiplexer: the current bin index selects which
// ledger / defer-buffer register is presented on o_act.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
// the bin-3 activity history bit pages the readout between the snapshot
// ledger and the bin-0 posted-write ledger
          case (i_bin)
2'd0: o_act <= ce_hist[3] ? n_p0 : n_iss;
2'd1: o_act <= ce_hist[3] ? n_w0 : n_ret;
2'd2: o_act <= ce_hist[3] ? {2'd0, b0_pend} : hold;
