// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
output reg  [2:0] last_delta, // bits differing between the last two samples
output reg  [3:0] o_idle_count // distractor: destination-domain activity meter
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;

   // Four-deep source-domain retiming pipeline.  The pointer counter sits at
   // the far end of the block from the launch flops, so the binary pointer is
   // carried over in four registered hops; the gray encoder is placed at the
   // last hop so both synchronizer chains launch from the same retimed value.
   reg  [3:0] p1, p2, p3, p4;
   wire [3:0] pgray = p4 ^ (p4 >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

   // second consumer's synchronizer chain onto the same gray pointer
   reg  [3:0] s1b, s2b;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;
   reg  [3:0] b1b, b2b;

   // round-robin refresh phase: 0 refreshes chain A, 1 refreshes chain B.
// Advances are no longer pinned to a phase: the issue pacer below spaces
// launches apart in time, which is what bounds either chain to a single
// gray transition between two of its own samples.
   reg        phase;
  // Programmable pointer depth.  The wrap modulus is carried as a mask that
  // is always one less than a power of two; it is widened one bit at a time
  // by i_incr pulses while the destination domain is parked (i_ce low).
  // Moving the wrap point invalidates everything already in flight, so a
  // depth change also drains the pointer and both synchronizer shadows.
  reg  [3:0] wrap_mask;

 // Issue/retire ledger for pointer advances.  n_issue logs advances pushed
 // into the source pointer, n_retire logs advances absorbed by the chain-A
 // shadow stage.  Both are plain free-running event counters that wrap at
 // four bits; only their difference is meaningful.
 reg  [3:0] n_issue;
 reg  [3:0] n_retire;

// Issue pacing.  gap_min is the programmed minimum number of destination
// cycles between two pointer advances and space_cnt counts the cycles since
// the last one, saturating once the pointer has been quiet for a while.
// Pacing the launches keeps the retiming chain from carrying two advances
// back to back, which is what the old fixed one-outstanding credit did.
reg  [2:0] gap_min;
reg  [2:0] space_cnt;

// Distractor bookkeeping: counts accepted advance pulses and bleeds down
// while the destination domain is parked.  Purely observational.
reg  [3:0] idle_count;

    initial begin
        wbin       = 4'd0;
       p1         = 4'd0;
       p2         = 4'd0;
       p3         = 4'd0;
       p4         = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
       s1b        = 4'd0;
       s2b        = 4'd0;
       b1b        = 4'd0;
       b2b        = 4'd0;
       phase      = 1'b0;
      wrap_mask  = 4'd1;
     n_issue    = 4'd0;
     n_retire   = 4'd0;
gap_min    = 3'd1;
space_cnt  = 3'd7;
idle_count = 4'd0;
o_idle_count = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

   // the same distance measure for the second chain
   wire [3:0] xrb = s1b ^ s2b;
   wire [2:0] delta_b = {2'b00, xrb[0]} + {2'b00, xrb[1]} +
                        {2'b00, xrb[2]} + {2'b00, xrb[3]};

   // one skew monitor is shared by both chains; it reports whichever chain
   // was refreshed on this phase
   wire [2:0] delta_mux = phase ? delta_b : delta;
   wire       skew_mux  = phase ? (s1b != s2b) : (sync1 != sync2);
  // depth reconfiguration is only accepted while the destination domain is
  // idle, and only up to the full four-bit pointer range
  wire       cfg_widen = !i_ce && i_incr && (wrap_mask != 4'd15);
 // once the pointer is at full depth the same parked pulses step the
 // issue-interval field instead of the mask; the field wraps back to one
 wire       cfg_pace  = !i_ce && i_incr && (wrap_mask == 4'd15);
// the ledger no longer gates issue; it only reports that an advance is
// somewhere between the pointer and the launch tap
 wire       ledger_busy = (n_issue != n_retire);
// pacing interlock: the previous launch must have had gap_min destination
// cycles to walk clear of the first retiming hop before another is issued
wire       pace_ok     = (space_cnt >= gap_min);
wire       ptr_adv     = i_ce && i_incr && pace_ok;
// an advance retires once it has cleared the last retiming hop and is
// therefore visible to whichever chain refreshes next
wire       shadow_adv  = i_ce && (p3 != p4);

    always @(posedge clk) begin
       if (cfg_widen) begin
           // new wrap point: grow the mask and drain the pointer pipeline
           wrap_mask <= (wrap_mask << 1) | 4'd1;
           wbin      <= 4'd0;
          p1        <= 4'd0;
          p2        <= 4'd0;
          p3        <= 4'd0;
          p4        <= 4'd0;
           sync1     <= 4'd0;
           sync2     <= 4'd0;
           b1        <= 4'd0;
           b2        <= 4'd0;
           s1b       <= 4'd0;
           s2b       <= 4'd0;
           b1b       <= 4'd0;
           b2b       <= 4'd0;
          n_issue   <= 4'd0;
          n_retire  <= 4'd0;
         space_cnt <= 3'd0;
      end else if (cfg_pace) begin
          // interval field steps and wraps back to its minimum of one
          gap_min <= (gap_min == 3'd7) ? 3'd1 : gap_min + 3'd1;
       end else if (i_ce) begin
            // source pointer
         wbin  <= (wbin + (ptr_adv ? 4'd1 : 4'd0)) & wrap_mask;

           // retiming hops toward the launch point
           p1 <= wbin;
           p2 <= p1;
           p3 <= p2;
           p4 <= p3;

           // ledger: log both sides of the advance
         n_issue  <= n_issue  + (ptr_adv    ? 4'd1 : 4'd0);
         n_retire <= n_retire + (shadow_adv ? 4'd1 : 4'd0);

           // issue pacer: restart on a launch, saturate while quiet
        if (ptr_adv)
            space_cnt <= 3'd0;
        else if (space_cnt != 3'd7)
            space_cnt <= space_cnt + 3'd1;

            // synchronizer chain
           if (!phase) begin
              sync1 <= pgray;
               sync2 <= sync1;
           end else begin
              s1b   <= pgray;
               s2b   <= s1b;
           end

            // shadow binary chain, structurally parallel to the chain above
           if (!phase) begin
              b1    <= p4;
               b2    <= b1;
           end else begin
              b1b   <= p4;
               b2b   <= b1b;
           end

            // monitor
           last_delta <= delta_mux;
           phase      <= ~phase;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
          if (skew_mux || ledger_busy)
                armed <= 1'b1;
        end
    end

   // ---- distractor: activity meter, independent of the pointer pipeline ----
   always @(posedge clk) begin
       if (i_ce && i_incr) begin
           if (idle_count != 4'd15)
               idle_count <= idle_count + 4'd1;
       end else if (!i_ce && idle_count != 4'd0) begin
           idle_count <= idle_count - 4'd1;
       end
       o_idle_count <= idle_count;
   end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

