module axi_addr_decoder (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire        cfg_sel,
    input  wire [63:0] cfg_base,
    input  wire [63:0] cfg_limit,
    input  wire        req_valid,
    input  wire [63:0] req_addr,
    input  wire        resp_valid,
    input  wire        resp_port,
    output wire        req_ready,
    output wire [1:0]  route,
    output wire        dec_err
);
    localparam [63:0] MAX_OUT = 64'd32;

    reg [63:0] base0  = 64'h0000000000000000;
    reg [63:0] limit0 = 64'h0000000000000FFF;
    reg [63:0] base1  = 64'h0000000000001000;
    reg [63:0] limit1 = 64'h0000000000001FFF;
    reg [63:0] cnt0   = 64'd0;
    reg [63:0] cnt1   = 64'd0;
    reg [63:0] total  = 64'd0;
    reg        armed  = 1'b0;

    wire hit0 = (req_addr >= base0) && (req_addr <= limit0);
    wire hit1 = !hit0 && (req_addr >= base1) && (req_addr <= limit1);

    assign route     = {hit1, hit0};
    assign dec_err   = req_valid && !hit0 && !hit1;
    assign req_ready = (total < MAX_OUT);

    wire do_resp  = resp_valid && (resp_port ? (cnt1 != 64'd0) : (cnt0 != 64'd0));
    wire do_issue = !do_resp && req_valid && (hit0 || hit1) && req_ready;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we) begin
                if (cfg_sel) begin
                    base1  <= cfg_base;
                    limit1 <= cfg_limit;
                end else begin
                    base0  <= cfg_base;
                    limit0 <= cfg_limit;
                end
            end
            if (do_resp) begin
                if (resp_port)
                    cnt1 <= cnt1 - 64'd1;
                else
                    cnt0 <= cnt0 - 64'd1;
                total <= total - 64'd1;
            end else if (do_issue) begin
                if (hit0)
                    cnt0 <= cnt0 + 64'd1;
                else
                    cnt1 <= cnt1 + 64'd1;
                total <= total + 64'd1;
                armed <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (cnt0 <= MAX_OUT);

    always @(posedge clk)
        if (armed) assert (cnt1 <= MAX_OUT);
endmodule

