module golay_scrub (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [3:0]  wr_addr,
    input  wire [11:0] wr_data,
    input  wire        inj,
    input  wire [3:0]  inj_addr,
    input  wire [23:0] inj_mask,
    input  wire        scrub_start,
    input  wire        scrub_done,
    output wire [31:0] o_corr_cnt,
    output wire [31:0] o_inj_cnt,
    output wire [11:0] o_syn,
    output wire        o_win
);
    function [11:0] brow;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:  brow = 12'hDC5;
                4'd1:  brow = 12'hB8B;
                4'd2:  brow = 12'h717;
                4'd3:  brow = 12'hE2D;
                4'd4:  brow = 12'hC5B;
                4'd5:  brow = 12'h8B7;
                4'd6:  brow = 12'h16F;
                4'd7:  brow = 12'h2DD;
                4'd8:  brow = 12'h5B9;
                4'd9:  brow = 12'hB71;
                4'd10: brow = 12'h6E3;
                default: brow = 12'hFFE;
            endcase
        end
    endfunction

    function [11:0] mulB;
        input [11:0] v;
        integer j;
        begin
            mulB = 12'h000;
            for (j = 0; j < 12; j = j + 1)
                if (v[j]) mulB = mulB ^ brow(j);
        end
    endfunction

    function [3:0] wt12;
        input [11:0] v;
        integer j;
        begin
            wt12 = 4'd0;
            for (j = 0; j < 12; j = j + 1)
                wt12 = wt12 + {3'b000, v[j]};
        end
    endfunction

    function [23:0] encode;
        input [11:0] d;
        begin
            encode = {d, mulB(d)};
        end
    endfunction

    function [11:0] syndrome;
        input [23:0] r;
        begin
            syndrome = mulB(r[23:12]) ^ r[11:0];
        end
    endfunction

    function [23:0] golay_err;
        input [11:0] s;
        reg [11:0] s2;
        reg found;
        integer j;
        begin
            golay_err = 24'h000000;
            found = 1'b0;
            if (wt12(s) <= 4'd3) begin
                golay_err = {12'h000, s};
                found = 1'b1;
            end
            for (j = 0; j < 12; j = j + 1)
                if (!found && (wt12(s ^ brow(j)) <= 4'd2)) begin
                    golay_err = {(12'h001 << j), (s ^ brow(j))};
                    found = 1'b1;
                end
            s2 = mulB(s);
            if (!found && (wt12(s2) <= 4'd3)) begin
                golay_err = {s2, 12'h000};
                found = 1'b1;
            end
            for (j = 0; j < 12; j = j + 1)
                if (!found && (wt12(s2 ^ brow(j)) <= 4'd2)) begin
                    golay_err = {(s2 ^ brow(j)), (12'h001 << j)};
                    found = 1'b1;
                end
        end
    endfunction

    reg [23:0] mem [0:15];
    reg [15:0] err_flag;
    reg [11:0] syn_reg;
    reg [3:0]  scan_ptr;
    reg [31:0] inj_cnt;
    reg [31:0] corr_cnt;
    reg        inj_seen;
    reg        win;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1)
            mem[k] = 24'h000000;
        err_flag = 16'h0000;
        syn_reg  = 12'h000;
        scan_ptr = 4'd0;
        inj_cnt  = 32'd0;
        corr_cnt = 32'd0;
        inj_seen = 1'b0;
        win      = 1'b0;
    end

    wire [23:0] cur     = mem[scan_ptr];
    wire [11:0] cur_syn = syndrome(cur);
    wire [23:0] cur_err = golay_err(cur_syn);

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1)
                mem[k] <= 24'h000000;
            err_flag <= 16'h0000;
            syn_reg  <= 12'h000;
            scan_ptr <= 4'd0;
            inj_cnt  <= 32'd0;
            corr_cnt <= 32'd0;
            inj_seen <= 1'b0;
            win      <= 1'b0;
        end else if (en) begin
            if (scrub_start)
                win <= 1'b1;
            else if (scrub_done)
                win <= 1'b0;
            if (win) begin
                syn_reg <= cur_syn;
                if (err_flag[scan_ptr]) begin
                    mem[scan_ptr]      <= cur ^ cur_err;
                    err_flag[scan_ptr] <= 1'b0;
                    corr_cnt           <= corr_cnt + 32'd1;
                end
                scan_ptr <= scan_ptr + 4'd1;
            end
            if (inj) begin
                mem[inj_addr]      <= mem[inj_addr] ^ inj_mask;
                err_flag[inj_addr] <= 1'b1;
                inj_cnt            <= inj_cnt + 32'd1;
                inj_seen           <= 1'b1;
            end
            if (wr) begin
                mem[wr_addr]      <= encode(wr_data);
                err_flag[wr_addr] <= 1'b0;
            end
        end
    end

    assign o_corr_cnt = corr_cnt;
    assign o_inj_cnt  = inj_cnt;
