    reg [31:0] tail = 32'd0;
    reg [6:0]  count = 7'd0;
    reg [5:0]  wptr = 6'd0;
    reg [5:0]  rptr = 6'd0;
    reg [63:0] valid = 64'd0;
    reg [31:0] tag_mem  [0:63];
    reg [31:0] data_mem [0:63];
