            out_valid <= 1'b0;
            if (drain) begin
                pre_drain <= 1'b0;
                if (busy) begin
                    out_valid <= 1'b1;
                    out_val <= cur;
                    out_cnt <= cnt;
                    busy <= 1'b0;
