    reg [2:0]  sel0, sel1, sel2, sel3;
    reg [13:0] stamp;
    reg [15:0] mem [0:63];
    reg [6:0]  wr_ptr, rd_ptr, occ;
    reg        pre_clr;
    reg        pv;

