module croc_wm_fifo (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        push,
    input  wire        pop,
    input  wire [63:0] wdata,
    input  wire        cfg_we,
    input  wire [63:0] cfg_af,
    input  wire [63:0] cfg_ae,
    input  wire        arm,
    input  wire        disarm,
    output wire [63:0] rdata,
    output wire        full,
    output wire        empty,
    output wire        afull,
    output wire        aempty
);
    reg [63:0] mem [0:15];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [63:0] count = 64'd0;
    reg [63:0] af_thr = 64'd14;
    reg [63:0] ae_thr = 64'd2;
    reg        full_q = 1'b0;
    reg        empty_q = 1'b1;
    reg        afull_q = 1'b0;
    reg        aempty_q = 1'b1;
    reg        win_q = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 64'd0;
    end

    wire do_push = push && !full_q;
    wire do_pop  = pop  && !empty_q;

    assign rdata  = mem[rptr];
    assign full   = full_q;
    assign empty  = empty_q;
    assign afull  = afull_q;
    assign aempty = aempty_q;

    always @(posedge clk) begin
        if (!rst_n) begin
            wptr     <= 4'd0;
            rptr     <= 4'd0;
            count    <= 64'd0;
            af_thr   <= 64'd14;
            ae_thr   <= 64'd2;
            full_q   <= 1'b0;
            empty_q  <= 1'b1;
            afull_q  <= 1'b0;
            aempty_q <= 1'b1;
            win_q    <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                af_thr <= cfg_af;
                ae_thr <= cfg_ae;
            end
            if (disarm)
                win_q <= 1'b0;
            else if (arm)
                win_q <= 1'b1;
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;
            if (do_push && !do_pop) begin
                count   <= count + 64'd1;
                empty_q <= 1'b0;
                if (count == 64'd15)
                    full_q <= 1'b1;
                if (count + 64'd1 == af_thr)
                    afull_q <= 1'b1;
                if (count == ae_thr)
                    aempty_q <= 1'b0;
            end else if (do_pop && !do_push) begin
                count <= count - 64'd1;
                if (count == 64'd1)
                    empty_q <= 1'b1;
                if (count == 64'd16)
                    full_q <= 1'b0;
                if (count == af_thr)
                    afull_q <= 1'b0;
                if (count - 64'd1 == ae_thr)
                    aempty_q <= 1'b1;
            end
        end
    end

    assert property (!(win_q && full_q && empty_q));
endmodule

