    wire        fa_busy;
    wire [6:0]  fa_idx;
    wire        fa_rsp_valid;
    wire [7:0]  fa_timer;
    wire        fr_fin_q;
    wire [1:0]  fr_phase;
    wire [31:0] fr_step_cnt;
    wire        f_fly_v_obs;
    wire        f_pend_v_obs;

    // multicast demux side
    wire [7:0]  m_valid;
    wire [7:0]  m_data;
    wire        m_done;
    wire        m_busy;
    wire [7:0]  m_delivered;
    wire [7:0]  m_mask;
    wire [1:0]  m_phase;

    // hold register: one routed result waiting to be replicated
    reg        g_v;
    reg [7:0]  g_mask;
    reg [6:0]  g_tag;
    initial begin
        g_v    = 1'b0;
        g_mask = 8'd0;
        g_tag  = 7'd0;
    end

    // classifier advances only when the hold is empty and the demux is free
    wire a_ce    = i_ce && !g_v && !m_busy;
    // routed result leaves the classifier pipe into the hold
    wire g_load  = a_ce && f_done;
    // demux is idle and takes the held result as a new multicast
    wire g_issue = i_ce && g_v && !m_busy;

    flow_route_pipe u_frp (
        .clk(clk),
        .rst(rst),
        .i_ce(a_ce),
        .req(req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .cfg_we(cfg_we),
        .cfg_addr(cfg_addr),
        .cfg_data(cfg_data),
        .o_done(f_done),
        .o_port(f_port),
        .o_rule(f_rule),
        .o_miss(f_miss),
        .o_stall(f_stall),
        .pend_v_o(f_pend_v),
        .fly_v_o(f_fly_v),
        .a_busy_o(fa_busy),
        .a_idx_o(fa_idx),
        .a_rsp_valid_o(fa_rsp_valid),
        .a_timer_o(fa_timer),
        .b_fin_q_o(fr_fin_q),
        .b_phase_o(fr_phase),
        .b_step_cnt_o(fr_step_cnt),
        .fly_v_obs(f_fly_v_obs),
        .pend_v_obs(f_pend_v_obs)
    );

    mcast_demux u_mc (
        .clk(clk),
        .i_reset(rst),
        .i_ce(i_ce),
        .i_arm(g_v),
        .i_mask(g_mask),
        .i_data({1'b0, g_tag}),
        .i_ready(i_ready),
        .o_valid(m_valid),
        .o_data(m_data),
        .o_done(m_done),
        .o_busy(m_busy),
        .delivered_o(m_delivered),
        .mask_o(m_mask),
        .phase_o(m_phase)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_v    <= 1'b0;
            g_mask <= 8'd0;
            g_tag  <= 7'd0;
        end else if (i_ce) begin
            if (g_load) begin
                g_v    <= 1'b1;
                g_mask <= f_port[7:0];
                g_tag  <= f_rule;
            end else if (g_issue) begin
                g_v    <= 1'b0;
            end
        end
    end

    assign o_valid     = m_valid;
    assign o_data      = m_data;
    assign o_done      = m_done;
    assign o_busy      = m_busy;
    assign o_miss      = f_miss;
    assign o_stall     = f_stall || g_v || m_busy;
    assign hold_v_o    = g_v;
    assign hold_mask_o = g_mask;
    assign hold_tag_o  = g_tag;

    // a multicast can only finish while no further routed result is parked
    always @(*)
        if (m_done)
            assert (!g_v);
endmodule

