module flow_hint_cache #(
  parameter ENTRIES = 4,
  parameter EW      = 2,
  parameter RW      = 7
) (
  input  wire                  clk,
  input  wire                  rst,
  input  wire                  ce,
  input  wire                  inv_en,
  input  wire [RW-1:0]         inv_idx,
  input  wire                  lk_en,
  input  wire [63:0]           lk_key,
  input  wire                  fill_en,
  input  wire [63:0]           fill_key,
  input  wire [RW-1:0]         fill_rule,
  output reg                   lk_hit,
  output reg  [RW-1:0]         lk_rule,
  output wire [ENTRIES-1:0]    ent_vld,
  output wire [ENTRIES*RW-1:0] ent_rules,
  output reg  [EW:0]           occ,
  output reg  [15:0]           hit_cnt,
  output reg  [15:0]           evict_cnt
);
  // cached flow key -> lowest matching rule index
  reg [63:0]        c_key  [0:ENTRIES-1];
  reg [RW-1:0]      c_rule [0:ENTRIES-1];
  reg [ENTRIES-1:0] c_vld;
  // second-chance reference bits and clock hand for replacement
  reg [ENTRIES-1:0] c_ref;
  reg [EW-1:0]      hand;

  integer n;
  initial begin
      for (n = 0; n < ENTRIES; n = n + 1) begin
          c_key[n]  = 64'd0;
          c_rule[n] = {RW{1'b0}};
      end
      c_vld     = {ENTRIES{1'b0}};
      c_ref     = {ENTRIES{1'b0}};
      hand      = {EW{1'b0}};
      hit_cnt   = 16'd0;
      evict_cnt = 16'd0;
  end

  assign ent_vld = c_vld;

  genvar g;
  generate
      for (g = 0; g < ENTRIES; g = g + 1) begin : g_rule_out
          assign ent_rules[g*RW +: RW] = c_rule[g];
      end
  endgenerate

  // lookup port: lowest-numbered valid entry holding the key
  reg [EW-1:0] lk_slot;
  integer jl;
  always @(*) begin
      lk_hit  = 1'b0;
      lk_rule = {RW{1'b0}};
      lk_slot = {EW{1'b0}};
      for (jl = ENTRIES - 1; jl >= 0; jl = jl - 1) begin
          if (c_vld[jl] && (c_key[jl] == lk_key)) begin
              lk_hit  = 1'b1;
              lk_rule = c_rule[jl];
              lk_slot = jl;
          end
      end
  end

  // fill port: refresh in place if the key is already cached
  reg          fl_hit;
  reg [EW-1:0] fl_slot;
  integer jf;
  always @(*) begin
      fl_hit  = 1'b0;
      fl_slot = {EW{1'b0}};
      for (jf = ENTRIES - 1; jf >= 0; jf = jf - 1) begin
          if (c_vld[jf] && (c_key[jf] == fill_key)) begin
              fl_hit  = 1'b1;
              fl_slot = jf;
          end
      end
  end

  // first free entry
  reg          fr_any;
  reg [EW-1:0] fr_slot;
  integer jv;
  always @(*) begin
      fr_any  = 1'b0;
      fr_slot = {EW{1'b0}};
      for (jv = ENTRIES - 1; jv >= 0; jv = jv - 1) begin
          if (!c_vld[jv]) begin
              fr_any  = 1'b1;
              fr_slot = jv;
          end
      end
  end

  // clock replacement: first entry from the hand with its reference bit clear
  reg          sc_any;
  reg [EW-1:0] sc_slot;
  reg [EW-1:0] sc_probe;
  integer js;
  always @(*) begin
      sc_any   = 1'b0;
      sc_slot  = hand;
      sc_probe = hand;
      for (js = ENTRIES - 1; js >= 0; js = js - 1) begin
          sc_probe = hand + js;
          if (!c_ref[sc_probe]) begin
              sc_any  = 1'b1;
              sc_slot = sc_probe;
          end
      end
  end

  // reference bits after the hand sweeps past the entries it skipped
  reg [ENTRIES-1:0] ref_swept;
  reg [EW-1:0]      sc_dist;
  reg [EW-1:0]      ent_dist;
  integer jr;
  always @(*) begin
      sc_dist   = sc_slot - hand;
      ent_dist  = {EW{1'b0}};
      ref_swept = {ENTRIES{1'b0}};
      for (jr = 0; jr < ENTRIES; jr = jr + 1) begin
          ent_dist      = jr - hand;
          ref_swept[jr] = c_ref[jr] && sc_any && (ent_dist > sc_dist);
      end
  end

  // a rule written at inv_idx can shadow any cached result at or above it
  reg [ENTRIES-1:0] inv_mask;
  integer ji;
  always @(*) begin
      for (ji = 0; ji < ENTRIES; ji = ji + 1)
          inv_mask[ji] = c_vld[ji] && (c_rule[ji] >= inv_idx);
  end

  integer jo;
  always @(*) begin
      occ = {(EW+1){1'b0}};
      for (jo = 0; jo < ENTRIES; jo = jo + 1)
          occ = occ + c_vld[jo];
  end

  wire [EW-1:0] vic_slot = fl_hit ? fl_slot : (fr_any ? fr_slot : sc_slot);

  always @(posedge clk) begin
      if (rst) begin
          c_vld     <= {ENTRIES{1'b0}};
          c_ref     <= {ENTRIES{1'b0}};
          hand      <= {EW{1'b0}};
          hit_cnt   <= 16'd0;
          evict_cnt <= 16'd0;
      end else if (ce) begin
          if (inv_en) begin
              c_vld <= c_vld & ~inv_mask;
              c_ref <= c_ref & ~inv_mask;
          end else begin
              if (lk_en && lk_hit) begin
                  c_ref[lk_slot] <= 1'b1;
                  if (hit_cnt != 16'hffff)
                      hit_cnt <= hit_cnt + 16'd1;
              end
              if (fill_en) begin
                  c_key[vic_slot]  <= fill_key;
                  c_rule[vic_slot] <= fill_rule;
                  c_vld[vic_slot]  <= 1'b1;
                  if (fl_hit)
                      c_ref[vic_slot] <= 1'b1;
                  else if (fr_any)
                      c_ref[vic_slot] <= 1'b0;
                  else begin
                      c_ref <= ref_swept;
                      hand  <= sc_slot + 1'b1;
                      if (evict_cnt != 16'hffff)
                          evict_cnt <= evict_cnt + 16'd1;
                  end
              end
          end
      end
  end
endmodule

module lookup_req_queue #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire          clk,
   input  wire          rst,
   input  wire          ce,
   input  wire          push,
   input  wire [63:0]   push_key,
   input  wire [15:0]   push_len,
   input  wire          pop,
   input  wire          tbl_wr,
   input  wire [6:0]    tbl_idx,
   output wire          ready,
   output wire          avail,
   output wire [63:0]   head_key,
   output wire [15:0]   head_len,
   output reg  [AW:0]   count,
   output reg  [6:0]    hwm,
   output wire [6:0]    scan_lim
);
   reg [63:0]   key_q [0:DEPTH-1];
   reg [15:0]   len_q [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW-1:0] rd_ptr;

   integer n;
   initial begin
       for (n = 0; n < DEPTH; n = n + 1) begin
           key_q[n] = 64'd0;
           len_q[n] = 16'd0;
       end
       wr_ptr = {AW{1'b0}};
       rd_ptr = {AW{1'b0}};
       count  = {(AW+1){1'b0}};
       hwm    = 7'd0;
   end

   assign ready    = (count != DEPTH);
   assign avail    = (count != {(AW+1){1'b0}});
   assign head_key = key_q[rd_ptr];
   assign head_len = len_q[rd_ptr];
   // highest rule index that can hold a valid entry, including a write landing this cycle
   assign scan_lim = (tbl_wr && (tbl_idx > hwm)) ? tbl_idx : hwm;

   wire do_push = push && ready;
   wire do_pop  = pop && avail;

   always @(posedge clk) begin
       if (rst) begin
           wr_ptr <= {AW{1'b0}};
           rd_ptr <= {AW{1'b0}};
           count  <= {(AW+1){1'b0}};
           hwm    <= 7'd0;
       end else if (ce) begin
           if (do_push) begin
               key_q[wr_ptr] <= push_key;
               len_q[wr_ptr] <= push_len;
               wr_ptr        <= wr_ptr + 1'b1;
           end
           if (do_pop)
               rd_ptr <= rd_ptr + 1'b1;
           if (do_push && !do_pop)
               count <= count + 1'b1;
           else if (do_pop && !do_push)
               count <= count - 1'b1;
           if (tbl_wr)
               hwm <= scan_lim;
       end
   end
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
output reg  [6:0]  rsp_rule,
output wire        req_ready,
output wire [2:0]  req_pending,
output wire [6:0]  scan_limit,
output reg         rsp_cached,
output wire [2:0]  cache_occ,
output wire [15:0] cache_hits,
output wire [15:0] cache_evicts
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;
reg [6:0]  q_lim;

wire        rq_ready;
wire        rq_avail;
wire [63:0] rq_key;
wire [15:0] rq_len;
wire [2:0]  rq_count;
wire [6:0]  rq_hwm;
wire [6:0]  rq_scan_lim;
reg         q_hint;
wire        fc_hit;
wire [6:0]  fc_rule;
wire [3:0]  fc_vld;
wire [27:0] fc_rules;
// start the scan at the cached rule unless a rule write lands this cycle
wire [6:0]  scan_start = (fc_hit && !wr_en) ? fc_rule : 7'd0;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
q_lim      = 7'd0;
       q_hint     = 1'b0;
       rsp_cached = 1'b0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
wire last = (idx == q_lim);

lookup_req_queue #(.DEPTH(4), .AW(2)) u_req_q (
    .clk      (clk),
    .rst      (rst),
    .ce       (i_ce),
    .push     (req),
    .push_key (req_key),
    .push_len (req_len),
    .pop      (!busy),
    .tbl_wr   (wr_en && !busy),
    .tbl_idx  (wr_idx),
    .ready    (rq_ready),
    .avail    (rq_avail),
    .head_key (rq_key),
    .head_len (rq_len),
    .count    (rq_count),
    .hwm      (rq_hwm),
    .scan_lim (rq_scan_lim)
);

assign req_ready   = rq_ready;
assign req_pending = rq_count;
assign scan_limit  = rq_hwm;

flow_hint_cache #(.ENTRIES(4), .EW(2), .RW(7)) u_fcache (
   .clk       (clk),
   .rst       (rst),
   .ce        (i_ce),
   .inv_en    (wr_en && !busy),
   .inv_idx   (wr_idx),
   .lk_en     (!busy && rq_avail && !wr_en),
   .lk_key    (rq_key),
   .fill_en   (busy && hit),
   .fill_key  (q_key),
   .fill_rule (idx),
   .lk_hit    (fc_hit),
   .lk_rule   (fc_rule),
   .ent_vld   (fc_vld),
   .ent_rules (fc_rules),
   .occ       (cache_occ),
   .hit_cnt   (cache_hits),
   .evict_cnt (cache_evicts)
);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
q_lim     <= 7'd0;
           q_hint     <= 1'b0;
           rsp_cached <= 1'b0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
if (rq_avail) begin
                    busy  <= 1'b1;
                   idx   <= scan_start;
timer <= {1'b0, rq_scan_lim} + 8'd1 - {1'b0, scan_start};
q_key <= rq_key;
q_len <= {48'd0, rq_len};
q_lim <= rq_scan_lim;
q_hint <= fc_hit && !wr_en;
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                   rsp_cached    <= q_hint;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                   rsp_cached    <= 1'b0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

