// Fault log for the packet steering MPU. Every steering decision the MPU
// rejects is recorded with its destination, deliver flag, matching rule and
// a timestamp. Software reads the oldest entry and manages the log through
// the region indexes the MPU table does not implement (24 and up). A new
// lookup is only admitted when the log can absorb a fault from every
// decision still travelling down the steering pipeline.
module mpu_fault_log #(
    parameter DEPTH   = 4,
    parameter PTR_W   = 2,
    parameter CNT_W   = 3,
    parameter STAMP_W = 8
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               i_ce,
    input  wire               lk_busy,
    input  wire               rsp_fire,
    input  wire [6:0]         rsp_rule,
    input  wire               acc_pending,
    input  wire [15:0]        acc_addr,
    input  wire               acc_write,
    input  wire               chk_hit,
    input  wire               chk_miss,
    input  wire               csr_we,
    input  wire [4:0]         csr_idx,
    input  wire [15:0]        csr_wdata,
    input  wire               lk_req,
    output wire               lk_ready,
    output wire               lk_req_gated,
    output wire [CNT_W-1:0]   log_count,
    output wire               log_empty,
    output wire               log_full,
    output wire [15:0]        head_addr,
    output wire               head_write,
    output wire [6:0]         head_rule,
    output wire [STAMP_W-1:0] head_stamp,
    output wire [3:0]         head_rep,
    output wire [CNT_W+2:0]   ctrl_rb,
    output wire               irq,
    output wire [7:0]         ok_cnt,
    output wire [7:0]         flt_cnt
);
    localparam [4:0]       CSR_CTRL  = 5'd24;
    localparam [4:0]       CSR_POP   = 5'd25;
    localparam [4:0]       CSR_FLUSH = 5'd26;
    localparam [4:0]       CSR_STCLR = 5'd27;
    localparam [PTR_W-1:0] LAST_PTR  = DEPTH - 1;
    localparam [CNT_W-1:0] FULL_CNT  = DEPTH;
    localparam [CNT_W-1:0] ONE_CNT   = 1;
    // log storage
    reg [15:0]        ent_addr  [0:DEPTH-1];
    reg               ent_write [0:DEPTH-1];
    reg [6:0]         ent_rule  [0:DEPTH-1];
    reg [STAMP_W-1:0] ent_stamp [0:DEPTH-1];
    reg [3:0]         ent_rep   [0:DEPTH-1];
    reg [PTR_W-1:0]   wr_ptr;
    reg [PTR_W-1:0]   rd_ptr;
    reg [CNT_W-1:0]   count;
    // shadow of the decision in the access register (rule) and of the
    // decision in the MPU check stage (rule, destination, deliver flag)
    reg [6:0]         g_rule;
    reg [15:0]        c_addr;
    reg               c_write;
    reg [6:0]         c_rule;
    // control, timestamp and statistics
    reg [STAMP_W-1:0] stamp;
    reg               irq_en;
    reg               halt_en;
    reg               coal_en;
    reg [CNT_W-1:0]   wmark;
    reg               irq_q;
    reg [7:0]         ok_q;
    reg [7:0]         flt_q;
    integer k;
    initial begin
        for (k = 0; k < DEPTH; k = k + 1) begin
            ent_addr[k]  = 16'd0;
            ent_write[k] = 1'b0;
            ent_rule[k]  = 7'd0;
            ent_stamp[k] = {STAMP_W{1'b0}};
            ent_rep[k]   = 4'd0;
        end
        wr_ptr  = {PTR_W{1'b0}};
        rd_ptr  = {PTR_W{1'b0}};
        count   = {CNT_W{1'b0}};
        g_rule  = 7'd0;
        c_addr  = 16'd0;
        c_write = 1'b0;
        c_rule  = 7'd0;
        stamp   = {STAMP_W{1'b0}};
        irq_en  = 1'b0;
        halt_en = 1'b0;
        coal_en = 1'b0;
        wmark   = {CNT_W{1'b0}};
        irq_q   = 1'b0;
        ok_q    = 8'd0;
        flt_q   = 8'd0;
    end
    // CSR decode on the region indexes the MPU table does not implement
    wire csr_ctrl  = csr_we && (csr_idx == CSR_CTRL);
    wire csr_pop   = csr_we && (csr_idx == CSR_POP);
    wire csr_flush = csr_we && (csr_idx == CSR_FLUSH);
    wire csr_stclr = csr_we && (csr_idx == CSR_STCLR);
    wire empty = (count == {CNT_W{1'b0}});
    wire full  = (count == FULL_CNT);
    // ring pointers; wr_prev names the newest entry
    wire [PTR_W-1:0] wr_prev = (wr_ptr == {PTR_W{1'b0}}) ? LAST_PTR : wr_ptr - 1'b1;
    wire [PTR_W-1:0] wr_nxt  = (wr_ptr == LAST_PTR) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
    wire [PTR_W-1:0] rd_nxt  = (rd_ptr == LAST_PTR) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
    wire pop = csr_pop && !empty && !csr_flush;
    // a fault repeating the newest entry is folded into it when enabled,
    // unless that entry is being popped in the same cycle
    wire same_as_newest = (ent_addr[wr_prev] == c_addr) &&
                          (ent_write[wr_prev] == c_write) &&
                          (ent_rule[wr_prev] == c_rule);
    wire coalesce = chk_miss && coal_en && !empty && !csr_flush && same_as_newest &&
                    !(pop && (count == ONE_CNT));
    wire push = chk_miss && !coalesce && !full;
    // every decision still in the steering pipeline may turn into a fault;
    // a new lookup is only started when the log can absorb all of them
    wire [CNT_W:0] reserved = {1'b0, count}
                            + {{CNT_W{1'b0}}, lk_busy}
                            + {{CNT_W{1'b0}}, rsp_fire}
                            + {{CNT_W{1'b0}}, acc_pending}
                            + {{CNT_W{1'b0}}, chk_miss};
    wire room   = (reserved < DEPTH);
    wire halted = halt_en && !empty;
    assign lk_ready     = room && !halted;
    assign lk_req_gated = lk_req && lk_ready;
    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < DEPTH; k = k + 1) begin
                ent_addr[k]  <= 16'd0;
                ent_write[k] <= 1'b0;
                ent_rule[k]  <= 7'd0;
                ent_stamp[k] <= {STAMP_W{1'b0}};
                ent_rep[k]   <= 4'd0;
            end
            wr_ptr  <= {PTR_W{1'b0}};
            rd_ptr  <= {PTR_W{1'b0}};
            count   <= {CNT_W{1'b0}};
            g_rule  <= 7'd0;
            c_addr  <= 16'd0;
            c_write <= 1'b0;
            c_rule  <= 7'd0;
            stamp   <= {STAMP_W{1'b0}};
            irq_en  <= 1'b0;
            halt_en <= 1'b0;
            coal_en <= 1'b0;
            wmark   <= {CNT_W{1'b0}};
            irq_q   <= 1'b0;
            ok_q    <= 8'd0;
            flt_q   <= 8'd0;
        end else if (i_ce) begin
            stamp <= stamp + 1'b1;
            if (rsp_fire)
                g_rule <= rsp_rule;
            if (acc_pending) begin
                c_addr  <= acc_addr;
                c_write <= acc_write;
                c_rule  <= g_rule;
            end
            if (csr_ctrl) begin
                irq_en  <= csr_wdata[0];
                halt_en <= csr_wdata[1];
                coal_en <= csr_wdata[2];
                wmark   <= csr_wdata[8 +: CNT_W];
            end
            if (push) begin
                ent_addr[wr_ptr]  <= c_addr;
                ent_write[wr_ptr] <= c_write;
                ent_rule[wr_ptr]  <= c_rule;
                ent_stamp[wr_ptr] <= stamp;
                ent_rep[wr_ptr]   <= 4'd0;
                wr_ptr            <= wr_nxt;
            end
            if (coalesce && (ent_rep[wr_prev] != 4'hF))
                ent_rep[wr_prev] <= ent_rep[wr_prev] + 4'd1;
            if (csr_flush) begin
                rd_ptr <= wr_ptr;
                count  <= push ? ONE_CNT : {CNT_W{1'b0}};
            end else begin
                if (pop)
                    rd_ptr <= rd_nxt;
                count <= count + {{(CNT_W-1){1'b0}}, push} - {{(CNT_W-1){1'b0}}, pop};
            end
            if (csr_stclr) begin
                ok_q  <= 8'd0;
                flt_q <= 8'd0;
            end else begin
                if (chk_hit && (ok_q != 8'hFF))
                    ok_q <= ok_q + 8'd1;
                if (chk_miss && (flt_q != 8'hFF))
                    flt_q <= flt_q + 8'd1;
            end
            irq_q <= irq_en && (((wmark != {CNT_W{1'b0}}) && (count >= wmark)) || halted);
        end
    end
    assign log_count  = count;
    assign log_empty  = empty;
    assign log_full   = full;
    assign head_addr  = empty ? 16'd0 : ent_addr[rd_ptr];
    assign head_write = !empty && ent_write[rd_ptr];
    assign head_rule  = empty ? 7'd0 : ent_rule[rd_ptr];
    assign head_stamp = empty ? {STAMP_W{1'b0}} : ent_stamp[rd_ptr];
    assign head_rep   = empty ? 4'd0 : ent_rep[rd_ptr];
    assign ctrl_rb    = {wmark, coal_en, halt_en, irq_en};
    assign irq        = irq_q;
    assign ok_cnt     = ok_q;
    assign flt_cnt    = flt_q;
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
    output wire        g_write_o
,
    output wire        lookup_ready,
    output wire        flog_irq,
    output wire [2:0]  flog_count_o,
    output wire        flog_empty_o,
    output wire        flog_full_o,
    output wire [15:0] flog_head_addr,
    output wire        flog_head_write,
    output wire [6:0]  flog_head_rule,
    output wire [7:0]  flog_head_stamp,
    output wire [3:0]  flog_head_rep,
    output wire [5:0]  flog_ctrl,
    output wire [7:0]  steer_ok_cnt,
    output wire [7:0]  steer_flt_cnt
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
    // fault log in front of the lookup request: every steering decision
    // still in flight holds one log slot in reserve
    localparam FLOG_DEPTH = 4;
    wire        flow_req;
    wire [2:0]  flog_count;
    wire        steer_fire = rsp_valid && rsp_hit;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .req(flow_req),
        .req_key(req_key),
        .req_len(req_len),
        .wr_en(wr_en),
        .wr_idx(wr_idx),
        .wr_key(wr_key),
        .wr_action(wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );
    mpu_fault_log #(
        .DEPTH(FLOG_DEPTH),
        .PTR_W(2),
        .CNT_W(3),
        .STAMP_W(8)
    ) u_flog (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .lk_busy(busy_a),
        .rsp_fire(steer_fire),
        .rsp_rule(rsp_rule),
        .acc_pending(g_valid),
        .acc_addr(g_addr),
        .acc_write(g_write),
        .chk_hit(hit_q),
        .chk_miss(miss_q),
        .csr_we(cfg_we),
        .csr_idx(cfg_idx),
        .csr_wdata(cfg_base),
        .lk_req(req),
        .lk_ready(lookup_ready),
        .lk_req_gated(flow_req),
        .log_count(flog_count),
        .log_empty(flog_empty_o),
        .log_full(flog_full_o),
        .head_addr(flog_head_addr),
        .head_write(flog_head_write),
        .head_rule(flog_head_rule),
        .head_stamp(flog_head_stamp),
        .head_rep(flog_head_rep),
        .ctrl_rb(flog_ctrl),
        .irq(flog_irq),
        .ok_cnt(steer_ok_cnt),
        .flt_cnt(steer_flt_cnt)
    );
    assign flog_count_o = flog_count;

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
    // a steering decision the MPU rejects always finds a free fault-log slot
    always @(posedge clk)
        if (miss_q)
            assert (flog_count < FLOG_DEPTH);
endmodule


Find strengthening invariant(s): facts about the design's reachable states that
(a) hold in every reachable state, and (b) together with the properties make
the set inductive, closing the proof by k-induction for EVERY assertion - an
invariant list that proves one assertion but leaves another failing is not a
solution.

Reply with JSON: {"invariants": ["<expr>", ...]} where each entry is a single
Verilog boolean expression over the module's signals. No other output.

Format rules for each expression - violations make the answer ungradeable:
- plain synthesizable Verilog only: no `->` (write `!a || b` for implication),
  no `$past` or other system functions, no SVA operators, no prose
- complete expressions only, with sized constants (`4'd8`, not `8`)
- TOP-LEVEL signal names only: every expression is evaluated in the top
  module. State inside a sub-module is visible only through the wires its
  instance drives - use those names. A sub-module-internal name (even
  without a dot) does not exist at the top level and voids the answer.

Here is a SystemVerilog design. It contains ONE OR MORE properties, written as
immediate assertions - count them; a design with sub-modules may carry an
assertion inside a sub-module as well as one at the top. Every assertion is
true of the design but the set is NOT provable by k-induction on its own: a
prover starting from an arbitrary state can violate at least one of them.

module fm_link_lock_ctl (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_comma,
   input  wire       i_sof_req,
   input  wire       i_eof,
   input  wire       i_dsym,
   input  wire       i_in_pkt,
   input  wire [7:0] i_byte,
   output reg        o_sof_ok,
   output reg        o_locked,
   output reg  [1:0] o_comma_run,
   output reg  [3:0] o_idle_run,
   output reg  [7:0] o_pkt_len,
   output reg        o_len_err,
   output reg  [7:0] o_pkt_sum,
   output reg  [7:0] o_last_sum,
   output reg  [7:0] o_sof_rej,
   output reg  [7:0] o_lock_loss,
   output wire [3:0] o_status
);
   localparam [1:0] RUN_MAX  = 2'd3;
   localparam [3:0] IDLE_MAX = 4'd15;
   localparam [7:0] LEN_MAX  = 8'd192;
   localparam [7:0] CNT_MAX  = 8'hff;
   // lock is held once four back-to-back commas have been observed
   wire lock_next = o_locked || (o_comma_run == RUN_MAX);
   // start-of-frame admission: a request is only honoured while armed
   wire sof_take  = i_sof_req && o_sof_ok;
   wire sof_drop  = i_sof_req && !o_sof_ok;
   // data symbols seen outside a packet are treated as line noise
   wire idle_dat  = i_dsym && !i_in_pkt;
   wire pkt_dat   = i_dsym && i_in_pkt;
   wire idle_trip = idle_dat && (o_idle_run == IDLE_MAX);
   wire len_hit   = pkt_dat && (o_pkt_len == LEN_MAX);
   assign o_status = {o_len_err, (o_sof_rej != 8'd0), o_sof_ok, o_locked};
   initial begin
       o_sof_ok = 1'b0; o_locked = 1'b0; o_comma_run = 2'd0; o_idle_run = 4'd0;
       o_pkt_len = 8'd0; o_len_err = 1'b0; o_pkt_sum = 8'd0; o_last_sum = 8'd0;
       o_sof_rej = 8'd0; o_lock_loss = 8'd0;
   end
   // alignment tracking: acquire on a comma run, drop on a noise run
   always @(posedge clk) begin
       if (rst) begin
           o_locked    <= 1'b0;
           o_comma_run <= 2'd0;
           o_idle_run  <= 4'd0;
           o_lock_loss <= 8'd0;
       end else if (i_comma) begin
           o_locked    <= lock_next;
           o_idle_run  <= 4'd0;
           if (o_comma_run != RUN_MAX) o_comma_run <= o_comma_run + 2'd1;
       end else if (idle_trip) begin
           o_locked    <= 1'b0;
           o_comma_run <= 2'd0;
           o_idle_run  <= 4'd0;
           if (o_locked && (o_lock_loss != CNT_MAX)) o_lock_loss <= o_lock_loss + 8'd1;
       end else if (idle_dat) begin
           o_idle_run  <= o_idle_run + 4'd1;
           if (!o_locked) o_comma_run <= 2'd0;
       end
   end
   // start-of-frame arm flag and refused-request counter
   always @(posedge clk) begin
       if (rst) begin
           o_sof_ok  <= 1'b0;
           o_sof_rej <= 8'd0;
       end else if (i_comma) begin
           o_sof_ok  <= !i_in_pkt && lock_next;
       end else if (sof_take) begin
           o_sof_ok  <= 1'b0;
       end else if (sof_drop) begin
           if (o_sof_rej != CNT_MAX) o_sof_rej <= o_sof_rej + 8'd1;
       end else if (i_eof) begin
           o_sof_ok  <= o_locked;
       end else if (idle_trip) begin
           o_sof_ok  <= 1'b0;
       end
   end
   // in-packet length limit and running checksum
   always @(posedge clk) begin
       if (rst) begin
           o_pkt_len  <= 8'd0;
           o_len_err  <= 1'b0;
