    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
