          q1_len  <= 6'd0;
          q1_csum <= 8'd0;
          q1_stat <= ST_NONE;
          q1_seq  <= q_seq;
          q1_par  <= ^q_seq;
      end else if (q_fill_sel[1]) begin
          q1_len  <= o_frm_len;
          q1_csum <= o_frm_csum;
