          q2_csum <= 8'd0;
          q2_stat <= ST_NONE;
          q2_seq  <= q_seq;
          q2_par  <= ^q_seq;
      end else if (q_fill_sel[2]) begin
          q2_len  <= o_frm_len;
          q2_csum <= o_frm_csum;
          q2_stat <= fill_stat;
          q2_par  <= fill_par ^ (^q2_seq);
      end
