  always @(posedge clk) begin
      if (rst) begin
          q3_len  <= 6'd0;
          q3_csum <= 8'd0;
          q3_stat <= ST_NONE;
          q3_seq  <= 4'd0;
          q3_par  <= 1'b0;
      end else if (q_rsv_sel[3]) begin
          q3_len  <= 6'd0;
          q3_csum <= 8'd0;
          q3_stat <= ST_NONE;
          q3_seq  <= q_seq;
          q3_par  <= ^q_seq;
      end else if (q_fill_sel[3]) begin
          q3_len  <= o_frm_len;
          q3_csum <= o_frm_csum;
          q3_stat <= fill_stat;
          q3_par  <= fill_par ^ (^q3_seq);
      end
