   // drops back to IDLE after VC1_REALIGN+1 frames without a fresh comma
   always @(posedge clk) begin
       if (rst) begin
           ph1               <= PH_IDLE;
           vc1_since_comma   <= 2'd0;
           vc1_last_trunc    <= 1'b0;
           vc1_last_runt     <= 1'b0;
           o_vc1_pkt_cnt     <= 32'd0;
