           o_sel_cnt       <= 8'd0;
           o_sel_rej_cnt   <= 8'd0;
           o_vc0_err_cnt   <= 8'd0;
           o_vc1_err_cnt   <= 8'd0;
           o_ifg_defer_cnt <= 8'd0;
