           if (do_sel) vc_sel <= i_data[0];
           if (sel_switch && (o_sel_cnt != 8'hFF))
               o_sel_cnt <= o_sel_cnt + 8'd1;
           if (sel_rej && (o_sel_rej_cnt != 8'hFF))
               o_sel_rej_cnt <= o_sel_rej_cnt + 8'd1;
           if (err0 && (o_vc0_err_cnt != 8'hFF))
               o_vc0_err_cnt <= o_vc0_err_cnt + 8'd1;
           if (err1 && (o_vc1_err_cnt != 8'hFF))
               o_vc1_err_cnt <= o_vc1_err_cnt + 8'd1;
