module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] ce,
    input wire [5:0] req,
    output wire [7:0] pool_o,
    output wire [5:0] win_o,
    output wire [5:0] done_o
);
    localparam [7:0] TOTAL = 8'd3;

    reg [7:0] pool;
    initial pool = TOTAL;

    wire w0, w1, w2, w3, w4, w5;
    wire [2:0] st0, st1, st2, st3, st4, st5;
    wire sa0, sa1, sa2, sa3, sa4, sa5;
    wire ra0, ra1, ra2, ra3, ra4, ra5;
    wire rs0, rs1, rs2, rs3, rs4, rs5;
    wire [7:0] rc0, rc1, rc2, rc3, rc4, rc5;

    // idle instances asking to open a power-down window
    wire c0, c1, c2, c3, c4, c5;
    assign c0 = ce[0] && req[0] && (st0 == 3'd0);
    assign c1 = ce[1] && req[1] && (st1 == 3'd0);
    assign c2 = ce[2] && req[2] && (st2 == 3'd0);
    assign c3 = ce[3] && req[3] && (st3 == 3'd0);
    assign c4 = ce[4] && req[4] && (st4 == 3'd0);
    assign c5 = ce[5] && req[5] && (st5 == 3'd0);

    // fixed-priority arbiter, one grant per cycle while a credit is free
    wire avail;
    assign avail = (pool != 8'd0);
    wire g0, g1, g2, g3, g4, g5;
    assign g0 = avail && c0;
    assign g1 = avail && c1 && !c0;
    assign g2 = avail && c2 && !c0 && !c1;
    assign g3 = avail && c3 && !c0 && !c1 && !c2;
    assign g4 = avail && c4 && !c0 && !c1 && !c2 && !c3;
    assign g5 = avail && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire acq;
    assign acq = g0 | g1 | g2 | g3 | g4 | g5;

    // windows closing this cycle return their credit
    wire r0, r1, r2, r3, r4, r5;
    assign r0 = ce[0] && (st0 == 3'd4);
    assign r1 = ce[1] && (st1 == 3'd4);
    assign r2 = ce[2] && (st2 == 3'd4);
    assign r3 = ce[3] && (st3 == 3'd4);
    assign r4 = ce[4] && (st4 == 3'd4);
    assign r5 = ce[5] && (st5 == 3'd4);
    wire [7:0] rel_cnt;
    assign rel_cnt = {7'd0, r0} + {7'd0, r1} + {7'd0, r2} + {7'd0, r3} + {7'd0, r4} + {7'd0, r5};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
        end else begin
            pool <= pool - {7'd0, acq} + rel_cnt;
        end
    end

    pg_seq u0 (.clk(clk), .rst(rst), .i_ce(ce[0]), .i_req(g0), .win(w0), .state(st0), .save_ack(sa0), .ramp_ack(ra0), .rest_ack(rs0), .ramp_cnt_o(rc0));
    pg_seq u1 (.clk(clk), .rst(rst), .i_ce(ce[1]), .i_req(g1), .win(w1), .state(st1), .save_ack(sa1), .ramp_ack(ra1), .rest_ack(rs1), .ramp_cnt_o(rc1));
    pg_seq u2 (.clk(clk), .rst(rst), .i_ce(ce[2]), .i_req(g2), .win(w2), .state(st2), .save_ack(sa2), .ramp_ack(ra2), .rest_ack(rs2), .ramp_cnt_o(rc2));
