           lk_nxt = lk_len;
       else if (lk_cnt != 4'd0)
           lk_nxt = lk_cnt - 4'd1;
       else
           lk_nxt = 4'd0;
       esc_nxt = esc || (miss_q && (flt_cnt == esc_thr));
       blk     = esc || (lk_cnt != 4'd0);
       blk_nxt = esc_nxt || (lk_nxt != 4'd0);
   end

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
