module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module tpu_dct_xpose (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] sample_in,
    output wire [15:0] acc_out
,
    output wire phase_o,
    output wire [15:0] rd_cnt_o,
    output wire [15:0] wr_cnt_o,
    output wire [15:0] wr_seen_o
);
    reg phase = 1'b0;
    reg [15:0] wr_cnt = 16'd0;
    reg [15:0] rd_cnt = 16'd0;
    reg [15:0] wr_seen = 16'd0;
    reg [15:0] acc = 16'd0;
    reg [15:0] coef_idx = 16'd0;
    reg [15:0] mem [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    assign acc_out = acc;

    function [15:0] cosv;
        input [2:0] idx;
        begin
            case (idx)
                3'd0: cosv = 16'd23170;
                3'd1: cosv = 16'd32138;
                3'd2: cosv = 16'd30274;
                3'd3: cosv = 16'd27246;
                3'd4: cosv = 16'd23170;
                3'd5: cosv = 16'd18205;
                3'd6: cosv = 16'd12540;
                default: cosv = 16'd6393;
            endcase
        end
    endfunction

    wire [31:0] row_prod = sample_in * cosv(coef_idx[2:0]);
    wire [15:0] rd_word = (rd_cnt < 16'd24) ? mem[rd_cnt[4:0]] : 16'd0;
    wire [31:0] col_prod = rd_word * cosv(coef_idx[2:0]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            wr_cnt <= 16'd0;
            rd_cnt <= 16'd0;
            wr_seen <= 16'd0;
            acc <= 16'd0;
            coef_idx <= 16'd0;
        end else if (en) begin
            if (!phase) begin
                if (wr_cnt == 16'd24) begin
                    phase <= 1'b1;
                    rd_cnt <= 16'd0;
                end else begin
                    if (wr_cnt < 16'd24) mem[wr_cnt[4:0]] <= row_prod[15:0];
                    wr_cnt <= wr_cnt + 16'd1;
                    wr_seen <= wr_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end
            end else begin
                if (rd_cnt < 16'd24) begin
                    acc <= acc + col_prod[15:0];
                    rd_cnt <= rd_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end else begin
                    phase <= 1'b0;
                    wr_cnt <= 16'd0;
                    wr_seen <= 16'd0;
                    rd_cnt <= 16'd0;
                    acc <= 16'd0;
                end
            end
        end
    end

    assert property (!phase || (rd_cnt <= wr_seen));
    assign phase_o = phase;
    assign rd_cnt_o = rd_cnt;
    assign wr_cnt_o = wr_cnt;
    assign wr_seen_o = wr_seen;
endmodule

module pg_dct_top (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    input wire dn_rdy,
    output wire [15:0] acc_out,
    output wire busy,
    output wire [15:0] xfer_o,
    output wire smp_pend
);
    wire a_win;
    wire [2:0] a_state;
    wire a_save_ack;
    wire a_ramp_ack;
    wire a_rest_ack;
    wire [7:0] a_ramp_cnt;

    wire b_phase;
    wire [15:0] b_rd_cnt;
    wire [15:0] b_wr_cnt;
    wire [15:0] b_wr_seen;
    wire [15:0] b_acc;

    reg [15:0] smp_q = 16'd0;
    reg smp_vld = 1'b0;
    reg [15:0] xfer_cnt = 16'd0;

    // A ramp step produces a new sample; B's write phase drains it when downstream is ready
    wire a_step = i_ce && (a_state == 3'd2);
    wire consume = smp_vld && dn_rdy && !b_phase && (b_wr_cnt != 16'd24);
    wire b_wrap = b_phase && (b_rd_cnt >= 16'd24);
    wire b_en = (smp_vld && dn_rdy) || b_phase || (b_wr_cnt == 16'd24);

    pg_seq u_seq (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
        .i_req(i_req),
        .win(a_win),
        .state(a_state),
        .save_ack(a_save_ack),
        .ramp_ack(a_ramp_ack),
        .rest_ack(a_rest_ack),
        .ramp_cnt_o(a_ramp_cnt)
    );

    tpu_dct_xpose u_dct (
        .clk(clk),
        .rst(rst),
        .en(b_en),
        .sample_in(smp_q),
        .acc_out(b_acc),
        .phase_o(b_phase),
        .rd_cnt_o(b_rd_cnt),
        .wr_cnt_o(b_wr_cnt),
        .wr_seen_o(b_wr_seen)
    );

    always @(posedge clk) begin
        if (rst) begin
            smp_q <= 16'd0;
            smp_vld <= 1'b0;
            xfer_cnt <= 16'd0;
        end else begin
            if (a_step) begin
                smp_q <= {8'd0, a_ramp_cnt};
                smp_vld <= 1'b1;
            end else if (consume) begin
