module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

   // Quarantine controller: a denied access closes the checker for lk_len
   // cycles (fault held, every access denied); denials beyond esc_thr in the
   // fault bucket escalate to a permanent lockout. Grants drain the bucket.
   reg [3:0] lk_len  = 4'd4;
   reg [2:0] esc_thr = 3'd7;
   reg [3:0] lk_cnt  = 4'd0;
   reg [2:0] flt_cnt = 3'd0;
   reg       esc     = 1'b0;
   reg [3:0] lk_nxt;
   reg       esc_nxt;
   reg       blk;
   reg       blk_nxt;
  // Write-protect quarantine: a denied write additionally closes the
  // checker for wlk_len cycles (the maximum window is used once write
  // denials arrive in a burst). Its countdown shares the decrementer with
  // the read quarantine and only advances once the read quarantine has
  // drained. Write denials fill their own bucket; overflow raises the same
  // permanent lockout as the read side.
  reg [3:0] wlk_len   = 4'd2;
  reg [2:0] wesc_thr  = 3'd3;
  reg [3:0] wlk_cnt   = 4'd0;
  reg [2:0] wflt_cnt  = 3'd0;
  reg [1:0] wburst    = 2'd0;
  reg       miss_wr_q = 1'b0;
  reg       hit_wr_q  = 1'b0;
  reg [3:0] wlk_nxt;
  reg       rd_miss;
  reg       rd_hit;
  reg       resc_hit;
  reg       wesc_hit;
   always @(*) begin
      rd_miss  = miss_q && !miss_wr_q;
      rd_hit   = hit_q && !hit_wr_q;
      if (rd_miss)
           lk_nxt = lk_len;
       else if (lk_cnt != 4'd0)
           lk_nxt = lk_cnt - 4'd1;
       else
           lk_nxt = 4'd0;
      if (miss_wr_q) begin
          if (wburst == 2'd3)
              wlk_nxt = 4'hF;
          else
              wlk_nxt = wlk_len;
      end else if ((wlk_cnt != 4'd0) && (lk_cnt == 4'd0))
          wlk_nxt = wlk_cnt - 4'd1;
      else
          wlk_nxt = wlk_cnt;
      resc_hit = rd_miss && (flt_cnt == esc_thr);
      wesc_hit = miss_wr_q && (wflt_cnt == wesc_thr);
      esc_nxt = esc || resc_hit || wesc_hit;
      blk     = esc || (lk_cnt != 4'd0) || (wlk_cnt != 4'd0);
      blk_nxt = esc_nxt || (lk_nxt != 4'd0) || (wlk_nxt != 4'd0);
   end

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
           if (cfg_we && pre_lock && (cfg_idx == 5'd24)) begin
               lk_len  <= cfg_base[3:0];
               esc_thr <= cfg_limit[2:0];
           end
          if (cfg_we && pre_lock && (cfg_idx == 5'd25)) begin
              wlk_len  <= cfg_base[3:0];
              wesc_thr <= cfg_limit[2:0];
          end
           lk_cnt <= lk_nxt;
          wlk_cnt <= wlk_nxt;
           esc    <= esc_nxt;
          if (rd_miss)
               flt_cnt <= flt_cnt + 3'd1;
          else if (rd_hit && (flt_cnt != 3'd0))
               flt_cnt <= flt_cnt - 3'd1;
          if (miss_wr_q)
              wflt_cnt <= wflt_cnt + 3'd1;
          else if (hit_wr_q && (wflt_cnt != 3'd0))
              wflt_cnt <= wflt_cnt - 3'd1;
          if (miss_wr_q) begin
              if (wburst != 2'd3)
                  wburst <= wburst + 2'd1;
          end else if (hit_q) begin
              wburst <= 2'd0;
          end
           hit_q  <= acc_valid && hit && !blk_nxt;
           miss_q <= acc_valid && (!hit || blk_nxt);
          hit_wr_q  <= acc_valid && acc_write && hit && !blk_nxt;
          miss_wr_q <= acc_valid && acc_write && (!hit || blk_nxt);
            grant  <= hit_q;
           fault  <= miss_q || blk;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

