        .w0_o(w0), .w1_o(w1), .w2_o(w2), .w3_o(w3), .w4_o(w4), .w5_o(w5)
    );

    // power-down windows retiring this cycle
    wire [5:0] closing;
    assign closing = {ce[5] && (st5 == 3'd4), ce[4] && (st4 == 3'd4), ce[3] && (st3 == 3'd4),
                      ce[2] && (st2 == 3'd4), ce[1] && (st1 == 3'd4), ce[0] && (st0 == 3'd4)};

    // completion report buffer and serializer toward the CRC checker
    reg       pend;
    reg [7:0] snap;
    reg [7:0] frame;
    initial begin
        pend = 1'b0; snap = 8'd0; frame = 8'd0;
    end

    wire launch;
    assign launch = pend && !busy && !rst;
    wire shift_en;
    assign shift_en = busy && b_ce;

    always @(posedge clk) begin
        if (rst) begin
            pend  <= 1'b0;
            snap  <= 8'd0;
            frame <= 8'd0;
        end else begin
            if (launch) begin
                frame <= snap;
                pend  <= 1'b0;
            end else if (shift_en) begin
                frame <= {frame[6:0], 1'b0};
            end
            if (!pend && (closing != 6'd0)) begin
                pend <= 1'b1;
                snap <= {2'b00, closing};
            end
        end
    end

    wire din_b;
    assign din_b = frame[7];

    crc_residue_chk u_crc (
        .clk(clk), .ce(b_ce), .start(launch), .din(din_b),
        .done(crc_done), .err(crc_err),
        .bitcnt_o(bitcnt), .busy_o(busy), .timer_o(timer)
    );

    // the check-bit half of every report frame is all zeros on the wire
    always @(*)
        if (busy && bitcnt >= 8'd8)
            assert (!din_b);

    assign rpt_pend_o  = pend;
    assign rpt_mask_o  = snap;
    assign rpt_shift_o = frame;
    assign bitcnt_obs = bitcnt;
    assign busy_obs = busy;
    assign frame_o = frame;
    assign pool_obs2 = pool;
    assign ra0_obs = ra0;
    assign ra1_obs = ra1;
    assign ra2_obs = ra2;
    assign ra3_obs = ra3;
    assign ra4_obs = ra4;
    assign ra5_obs = ra5;
    assign rc0_obs = rc0;
    assign rc1_obs = rc1;
    assign rc2_obs = rc2;
    assign rc3_obs = rc3;
    assign rc4_obs = rc4;
    assign rc5_obs = rc5;
    assign rs0_obs = rs0;
    assign rs1_obs = rs1;
    assign rs2_obs = rs2;
    assign rs3_obs = rs3;
    assign rs4_obs = rs4;
    assign rs5_obs = rs5;
    assign sa0_obs = sa0;
    assign sa1_obs = sa1;
    assign sa2_obs = sa2;
    assign sa3_obs = sa3;
    assign sa4_obs = sa4;
    assign sa5_obs = sa5;
    assign snap_o = snap;
    assign st0_obs = st0;
    assign st1_obs = st1;
    assign st2_obs = st2;
    assign st3_obs = st3;
    assign st4_obs = st4;
    assign st5_obs = st5;
    assign timer_obs = timer;
    assign w0_obs = w0;
    assign w1_obs = w1;
    assign w2_obs = w2;
    assign w3_obs = w3;
    assign w4_obs = w4;
    assign w5_obs = w5;
