module pg_crc_quad (
    input  wire clk,
    input  wire rst,
    input  wire [23:0] ce,
    input  wire [23:0] req,
    input  wire [3:0] b_ce,
    output wire [7:0] credit_o,
    output wire [3:0] grant_o,
    output wire [23:0] win_o,
    output wire [3:0] crc_done_o,
    output wire [3:0] crc_err_o
);
    localparam [7:0] OTOTAL = 8'd4;

    reg [7:0] credit;
    initial credit = OTOTAL;

    wire [5:0] ce_i0, ce_i1, ce_i2, ce_i3;
    wire [5:0] rq_i0, rq_i1, rq_i2, rq_i3;
    assign ce_i0 = ce[5:0];
    assign ce_i1 = ce[11:6];
    assign ce_i2 = ce[17:12];
    assign ce_i3 = ce[23:18];
    assign rq_i0 = req[5:0];
    assign rq_i1 = req[11:6];
    assign rq_i2 = req[17:12];
    assign rq_i3 = req[23:18];

    wire [7:0] pool_i0, pool_i1, pool_i2, pool_i3;
    wire [7:0] bitcnt_i0, bitcnt_i1, bitcnt_i2, bitcnt_i3;
    wire [7:0] timer_i0, timer_i1, timer_i2, timer_i3;
    wire [7:0] frame_i0, frame_i1, frame_i2, frame_i3;
    wire [7:0] snap_i0, snap_i1, snap_i2, snap_i3;
    wire busy_i0, busy_i1, busy_i2, busy_i3;

    wire w0_i0, w1_i0, w2_i0, w3_i0, w4_i0, w5_i0;
    wire [2:0] st0_i0, st1_i0, st2_i0, st3_i0, st4_i0, st5_i0;
    wire sa0_i0, sa1_i0, sa2_i0, sa3_i0, sa4_i0, sa5_i0;
    wire ra0_i0, ra1_i0, ra2_i0, ra3_i0, ra4_i0, ra5_i0;
    wire rs0_i0, rs1_i0, rs2_i0, rs3_i0, rs4_i0, rs5_i0;
    wire [7:0] rc0_i0, rc1_i0, rc2_i0, rc3_i0, rc4_i0, rc5_i0;

    wire w0_i1, w1_i1, w2_i1, w3_i1, w4_i1, w5_i1;
    wire [2:0] st0_i1, st1_i1, st2_i1, st3_i1, st4_i1, st5_i1;
    wire sa0_i1, sa1_i1, sa2_i1, sa3_i1, sa4_i1, sa5_i1;
    wire ra0_i1, ra1_i1, ra2_i1, ra3_i1, ra4_i1, ra5_i1;
    wire rs0_i1, rs1_i1, rs2_i1, rs3_i1, rs4_i1, rs5_i1;
    wire [7:0] rc0_i1, rc1_i1, rc2_i1, rc3_i1, rc4_i1, rc5_i1;

    wire w0_i2, w1_i2, w2_i2, w3_i2, w4_i2, w5_i2;
    wire [2:0] st0_i2, st1_i2, st2_i2, st3_i2, st4_i2, st5_i2;
    wire sa0_i2, sa1_i2, sa2_i2, sa3_i2, sa4_i2, sa5_i2;
    wire ra0_i2, ra1_i2, ra2_i2, ra3_i2, ra4_i2, ra5_i2;
    wire rs0_i2, rs1_i2, rs2_i2, rs3_i2, rs4_i2, rs5_i2;
    wire [7:0] rc0_i2, rc1_i2, rc2_i2, rc3_i2, rc4_i2, rc5_i2;

    wire w0_i3, w1_i3, w2_i3, w3_i3, w4_i3, w5_i3;
    wire [2:0] st0_i3, st1_i3, st2_i3, st3_i3, st4_i3, st5_i3;
    wire sa0_i3, sa1_i3, sa2_i3, sa3_i3, sa4_i3, sa5_i3;
    wire ra0_i3, ra1_i3, ra2_i3, ra3_i3, ra4_i3, ra5_i3;
    wire rs0_i3, rs1_i3, rs2_i3, rs3_i3, rs4_i3, rs5_i3;
    wire [7:0] rc0_i3, rc1_i3, rc2_i3, rc3_i3, rc4_i3, rc5_i3;

    // sequencers sitting idle, and windows retiring this cycle, per instance
    wire [5:0] idle_i0, idle_i1, idle_i2, idle_i3;
    wire [5:0] fin_i0, fin_i1, fin_i2, fin_i3;
    assign idle_i0 = {st5_i0 == 3'd0, st4_i0 == 3'd0, st3_i0 == 3'd0, st2_i0 == 3'd0, st1_i0 == 3'd0, st0_i0 == 3'd0};
    assign idle_i1 = {st5_i1 == 3'd0, st4_i1 == 3'd0, st3_i1 == 3'd0, st2_i1 == 3'd0, st1_i1 == 3'd0, st0_i1 == 3'd0};
    assign idle_i2 = {st5_i2 == 3'd0, st4_i2 == 3'd0, st3_i2 == 3'd0, st2_i2 == 3'd0, st1_i2 == 3'd0, st0_i2 == 3'd0};
    assign idle_i3 = {st5_i3 == 3'd0, st4_i3 == 3'd0, st3_i3 == 3'd0, st2_i3 == 3'd0, st1_i3 == 3'd0, st0_i3 == 3'd0};
    assign fin_i0 = ce_i0 & {st5_i0 == 3'd4, st4_i0 == 3'd4, st3_i0 == 3'd4, st2_i0 == 3'd4, st1_i0 == 3'd4, st0_i0 == 3'd4};
    assign fin_i1 = ce_i1 & {st5_i1 == 3'd4, st4_i1 == 3'd4, st3_i1 == 3'd4, st2_i1 == 3'd4, st1_i1 == 3'd4, st0_i1 == 3'd4};
    assign fin_i2 = ce_i2 & {st5_i2 == 3'd4, st4_i2 == 3'd4, st3_i2 == 3'd4, st2_i2 == 3'd4, st1_i2 == 3'd4, st0_i2 == 3'd4};
    assign fin_i3 = ce_i3 & {st5_i3 == 3'd4, st4_i3 == 3'd4, st3_i3 == 3'd4, st2_i3 == 3'd4, st1_i3 == 3'd4, st0_i3 == 3'd4};

    // an instance can open a window this cycle only if its local pool has room
    wire want_i0, want_i1, want_i2, want_i3;
    assign want_i0 = (pool_i0 != 8'd0) && ((ce_i0 & rq_i0 & idle_i0) != 6'd0);
    assign want_i1 = (pool_i1 != 8'd0) && ((ce_i1 & rq_i1 & idle_i1) != 6'd0);
    assign want_i2 = (pool_i2 != 8'd0) && ((ce_i2 & rq_i2 & idle_i2) != 6'd0);
    assign want_i3 = (pool_i3 != 8'd0) && ((ce_i3 & rq_i3 & idle_i3) != 6'd0);

    // global budget arbiter: one new window per cycle chip-wide
    wire avail;
    assign avail = (credit != 8'd0);
    wire gnt0, gnt1, gnt2, gnt3;
    assign gnt0 = avail && want_i0;
    assign gnt1 = avail && want_i1 && !want_i0;
    assign gnt2 = avail && want_i2 && !want_i0 && !want_i1;
    assign gnt3 = avail && want_i3 && !want_i0 && !want_i1 && !want_i2;
    wire acq;
    assign acq = gnt0 | gnt1 | gnt2 | gnt3;

    wire [5:0] qrq_i0, qrq_i1, qrq_i2, qrq_i3;
    assign qrq_i0 = rq_i0 & {6{gnt0}};
    assign qrq_i1 = rq_i1 & {6{gnt1}};
    assign qrq_i2 = rq_i2 & {6{gnt2}};
    assign qrq_i3 = rq_i3 & {6{gnt3}};

    wire [7:0] rel_i0, rel_i1, rel_i2, rel_i3, rel_cnt;
    assign rel_i0 = {7'd0, fin_i0[0]} + {7'd0, fin_i0[1]} + {7'd0, fin_i0[2]} + {7'd0, fin_i0[3]} + {7'd0, fin_i0[4]} + {7'd0, fin_i0[5]};
    assign rel_i1 = {7'd0, fin_i1[0]} + {7'd0, fin_i1[1]} + {7'd0, fin_i1[2]} + {7'd0, fin_i1[3]} + {7'd0, fin_i1[4]} + {7'd0, fin_i1[5]};
    assign rel_i2 = {7'd0, fin_i2[0]} + {7'd0, fin_i2[1]} + {7'd0, fin_i2[2]} + {7'd0, fin_i2[3]} + {7'd0, fin_i2[4]} + {7'd0, fin_i2[5]};
    assign rel_i3 = {7'd0, fin_i3[0]} + {7'd0, fin_i3[1]} + {7'd0, fin_i3[2]} + {7'd0, fin_i3[3]} + {7'd0, fin_i3[4]} + {7'd0, fin_i3[5]};
    assign rel_cnt = rel_i0 + rel_i1 + rel_i2 + rel_i3;

    always @(posedge clk) begin
        if (rst) begin
            credit <= OTOTAL;
        end else begin
            credit <= credit - {7'd0, acq} + rel_cnt;
        end
    end

    pg_crc_top u0 (
        .clk(clk), .rst(rst), .ce(ce_i0), .req(qrq_i0), .b_ce(b_ce[0]),
        .pool_o(), .win_o(win_o[5:0]), .done_o(), .crc_done(crc_done_o[0]), .crc_err(crc_err_o[0]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i0), .busy_obs(busy_i0), .frame_o(frame_i0), .pool_obs2(pool_i0),
        .ra0_obs(ra0_i0), .ra1_obs(ra1_i0), .ra2_obs(ra2_i0), .ra3_obs(ra3_i0), .ra4_obs(ra4_i0), .ra5_obs(ra5_i0),
        .rc0_obs(rc0_i0), .rc1_obs(rc1_i0), .rc2_obs(rc2_i0), .rc3_obs(rc3_i0), .rc4_obs(rc4_i0), .rc5_obs(rc5_i0),
        .rs0_obs(rs0_i0), .rs1_obs(rs1_i0), .rs2_obs(rs2_i0), .rs3_obs(rs3_i0), .rs4_obs(rs4_i0), .rs5_obs(rs5_i0),
        .sa0_obs(sa0_i0), .sa1_obs(sa1_i0), .sa2_obs(sa2_i0), .sa3_obs(sa3_i0), .sa4_obs(sa4_i0), .sa5_obs(sa5_i0),
        .snap_o(snap_i0),
        .st0_obs(st0_i0), .st1_obs(st1_i0), .st2_obs(st2_i0), .st3_obs(st3_i0), .st4_obs(st4_i0), .st5_obs(st5_i0),
        .timer_obs(timer_i0),
        .w0_obs(w0_i0), .w1_obs(w1_i0), .w2_obs(w2_i0), .w3_obs(w3_i0), .w4_obs(w4_i0), .w5_obs(w5_i0)
    );

    pg_crc_top u1 (
        .clk(clk), .rst(rst), .ce(ce_i1), .req(qrq_i1), .b_ce(b_ce[1]),
        .pool_o(), .win_o(win_o[11:6]), .done_o(), .crc_done(crc_done_o[1]), .crc_err(crc_err_o[1]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i1), .busy_obs(busy_i1), .frame_o(frame_i1), .pool_obs2(pool_i1),
        .ra0_obs(ra0_i1), .ra1_obs(ra1_i1), .ra2_obs(ra2_i1), .ra3_obs(ra3_i1), .ra4_obs(ra4_i1), .ra5_obs(ra5_i1),
        .rc0_obs(rc0_i1), .rc1_obs(rc1_i1), .rc2_obs(rc2_i1), .rc3_obs(rc3_i1), .rc4_obs(rc4_i1), .rc5_obs(rc5_i1),
        .rs0_obs(rs0_i1), .rs1_obs(rs1_i1), .rs2_obs(rs2_i1), .rs3_obs(rs3_i1), .rs4_obs(rs4_i1), .rs5_obs(rs5_i1),
        .sa0_obs(sa0_i1), .sa1_obs(sa1_i1), .sa2_obs(sa2_i1), .sa3_obs(sa3_i1), .sa4_obs(sa4_i1), .sa5_obs(sa5_i1),
        .snap_o(snap_i1),
        .st0_obs(st0_i1), .st1_obs(st1_i1), .st2_obs(st2_i1), .st3_obs(st3_i1), .st4_obs(st4_i1), .st5_obs(st5_i1),
        .timer_obs(timer_i1),
        .w0_obs(w0_i1), .w1_obs(w1_i1), .w2_obs(w2_i1), .w3_obs(w3_i1), .w4_obs(w4_i1), .w5_obs(w5_i1)
    );

    pg_crc_top u2 (
        .clk(clk), .rst(rst), .ce(ce_i2), .req(qrq_i2), .b_ce(b_ce[2]),
        .pool_o(), .win_o(win_o[17:12]), .done_o(), .crc_done(crc_done_o[2]), .crc_err(crc_err_o[2]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i2), .busy_obs(busy_i2), .frame_o(frame_i2), .pool_obs2(pool_i2),
        .ra0_obs(ra0_i2), .ra1_obs(ra1_i2), .ra2_obs(ra2_i2), .ra3_obs(ra3_i2), .ra4_obs(ra4_i2), .ra5_obs(ra5_i2),
        .rc0_obs(rc0_i2), .rc1_obs(rc1_i2), .rc2_obs(rc2_i2), .rc3_obs(rc3_i2), .rc4_obs(rc4_i2), .rc5_obs(rc5_i2),
        .rs0_obs(rs0_i2), .rs1_obs(rs1_i2), .rs2_obs(rs2_i2), .rs3_obs(rs3_i2), .rs4_obs(rs4_i2), .rs5_obs(rs5_i2),
        .sa0_obs(sa0_i2), .sa1_obs(sa1_i2), .sa2_obs(sa2_i2), .sa3_obs(sa3_i2), .sa4_obs(sa4_i2), .sa5_obs(sa5_i2),
        .snap_o(snap_i2),
        .st0_obs(st0_i2), .st1_obs(st1_i2), .st2_obs(st2_i2), .st3_obs(st3_i2), .st4_obs(st4_i2), .st5_obs(st5_i2),
        .timer_obs(timer_i2),
        .w0_obs(w0_i2), .w1_obs(w1_i2), .w2_obs(w2_i2), .w3_obs(w3_i2), .w4_obs(w4_i2), .w5_obs(w5_i2)
    );

    pg_crc_top u3 (
        .clk(clk), .rst(rst), .ce(ce_i3), .req(qrq_i3), .b_ce(b_ce[3]),
        .pool_o(), .win_o(win_o[23:18]), .done_o(), .crc_done(crc_done_o[3]), .crc_err(crc_err_o[3]),
        .rpt_pend_o(), .rpt_mask_o(), .rpt_shift_o(),
        .bitcnt_obs(bitcnt_i3), .busy_obs(busy_i3), .frame_o(frame_i3), .pool_obs2(pool_i3),
        .ra0_obs(ra0_i3), .ra1_obs(ra1_i3), .ra2_obs(ra2_i3), .ra3_obs(ra3_i3), .ra4_obs(ra4_i3), .ra5_obs(ra5_i3),
        .rc0_obs(rc0_i3), .rc1_obs(rc1_i3), .rc2_obs(rc2_i3), .rc3_obs(rc3_i3), .rc4_obs(rc4_i3), .rc5_obs(rc5_i3),
        .rs0_obs(rs0_i3), .rs1_obs(rs1_i3), .rs2_obs(rs2_i3), .rs3_obs(rs3_i3), .rs4_obs(rs4_i3), .rs5_obs(rs5_i3),
        .sa0_obs(sa0_i3), .sa1_obs(sa1_i3), .sa2_obs(sa2_i3), .sa3_obs(sa3_i3), .sa4_obs(sa4_i3), .sa5_obs(sa5_i3),
        .snap_o(snap_i3),
        .st0_obs(st0_i3), .st1_obs(st1_i3), .st2_obs(st2_i3), .st3_obs(st3_i3), .st4_obs(st4_i3), .st5_obs(st5_i3),
        .timer_obs(timer_i3),
        .w0_obs(w0_i3), .w1_obs(w1_i3), .w2_obs(w2_i3), .w3_obs(w3_i3), .w4_obs(w4_i3), .w5_obs(w5_i3)
    );

    // the chip-wide budget never exceeds what was provisioned
    always @(posedge clk)
        assert (credit <= OTOTAL);

    assign credit_o = credit;
    assign grant_o = {gnt3, gnt2, gnt1, gnt0};
