module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
   output reg          done,
   output wire         beat_ready,
   output wire [1:0]   q_level,
   output wire [127:0] q_head
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

   // two-entry beat staging queue; the start comparator is evaluated on
   // entry so a later watchpoint rewrite cannot retroactively change it
   reg [127:0] q_data0, q_data1;
   reg q_st0, q_st1;
   reg q_rd, q_wr;
   reg [1:0] q_cnt;
   initial q_data0 = 128'h0;
   initial q_data1 = 128'h0;
   initial q_st0 = 1'b0;
   initial q_st1 = 1'b0;
   initial q_rd = 1'b0;
   initial q_wr = 1'b0;
   initial q_cnt = 2'd0;

   wire q_full = (q_cnt == 2'd2);
   wire q_hv   = (q_cnt != 2'd0);
   wire q_hst  = q_rd ? q_st1 : q_st0;
   assign q_head     = q_rd ? q_data1 : q_data0;
   assign q_level    = q_cnt;
   assign beat_ready = !q_full;
   // pops stall while the watchpoint port is being written
   wire q_pop  = en && !clr_cmd && q_hv && !wr_en;
   wire q_push = en && !clr_cmd && beat_valid && (!q_full || q_pop);

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
   wire match1 = q_hv && (((q_head ^ wval1) & wmask1) == 128'h0);
   wire start_hit = (fsm == S_ARMED) && match0;

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
           S_ARMED: if (q_pop && q_hst)  fsm_nxt = S_RUN;
           S_RUN:   if (q_pop && match1) fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
           q_data0 <= 128'h0;
           q_data1 <= 128'h0;
           q_st0 <= 1'b0;
           q_st1 <= 1'b0;
           q_rd <= 1'b0;
           q_wr <= 1'b0;
           q_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
               q_cnt <= 2'd0;
               q_rd <= 1'b0;
               q_wr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
               if (start_hit && q_push) started_seen <= 1'b1;
               if (q_push) begin
                   if (q_wr) begin
                       q_data1 <= beat_data;
                       q_st1   <= start_hit;
                   end else begin
                       q_data0 <= beat_data;
                       q_st0   <= start_hit;
                   end
                   q_wr <= !q_wr;
               end
               if (q_pop) q_rd <= !q_rd;
               if (q_push && !q_pop) q_cnt <= q_cnt + 2'd1;
               else if (q_pop && !q_push) q_cnt <= q_cnt - 2'd1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
