                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
