                    if (ramp_ack)
                        state <= S_REST;
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
            // Second power domain: takes requests that arrive while domain A is busy
            case (state_b)
