                        save_ack_b <= 1'b1;
                        ramp_cnt <= 8'd0;
                        rail_busy <= 1'b1;
                        rail_owner <= 1'b1;
                        state_b <= S_RAMP;
                    end else if (rail_stall_cnt != 8'hFF) begin
                        rail_stall_cnt <= rail_stall_cnt + 8'd1;
                    end
                end
                S_RAMP: begin
                    if (ramp_ack_b)
                        state_b <= S_REST;
                end
                S_REST: begin
                    rest_ack_b <= 1'b1;
                    state_b <= S_DONE;
                end
                S_DONE: begin
                    state_b <= S_IDLE;
                end
                default: begin
                    state_b <= S_IDLE;
                end
            endcase
            // Shared ramp regulator: one ramp at a time, completion reported to the grant holder
            if (rail_busy) begin
                if (ramp_cnt == RAMP_LAST) begin
                    rail_busy <= 1'b0;
                    if (rail_owner)
                        ramp_ack_b <= 1'b1;
                    else
                        ramp_ack <= 1'b1;
                end else begin
                    ramp_cnt <= ramp_cnt + 8'd1;
                end
            end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

