        .cnt_o(t2_cnt), .rd_ptr_o(t2_rd_ptr),
        .st0_idx_o(t2_st0_idx), .st0_v_o(t2_st0_v), .st1_idx_o(t2_st1_idx), .st1_v_o(t2_st1_v),
        .st2_idx_o(t2_st2_idx), .st2_v_o(t2_st2_v), .st3_idx_o(t2_st3_idx), .st3_v_o(t2_st3_v));

    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(t3_en), .start(start[3]), .stop(stop[3]),
        .out_q(t3_out_q), .out_v(t3_out_v), .pipe_vld(t3_pipe_vld), .out_tag(t3_out_tag), .dbg_stat(t3_dbg),
        .cnt_o(t3_cnt), .rd_ptr_o(t3_rd_ptr),
        .st0_idx_o(t3_st0_idx), .st0_v_o(t3_st0_v), .st1_idx_o(t3_st1_idx), .st1_v_o(t3_st1_v),
        .st2_idx_o(t3_st2_idx), .st2_v_o(t3_st2_v), .st3_idx_o(t3_st3_idx), .st3_v_o(t3_st3_v));

    // credit return: frame end (last ROM index leaving stage 3) or lane stopped
    wire r0 = h0 && en && (stop[0] || (!start[0] && t0_st3_v && t0_st3_idx == 3'd7));
    wire r1 = h1 && en && (stop[1] || (!start[1] && t1_st3_v && t1_st3_idx == 3'd7));
    wire r2 = h2 && en && (stop[2] || (!start[2] && t2_st3_v && t2_st3_idx == 3'd7));
    wire r3 = h3 && en && (stop[3] || (!start[3] && t3_st3_v && t3_st3_idx == 3'd7));

    // one grant per cycle, fixed priority, only from a non-empty pool
    wire credit_ok = en && (pool != 2'd0);
    wire g0 = credit_ok && req[0] && !h0;
    wire g1 = credit_ok && req[1] && !h1 && !g0;
    wire g2 = credit_ok && req[2] && !h2 && !g0 && !g1;
    wire g3 = credit_ok && req[3] && !h3 && !g0 && !g1 && !g2;
    wire g_any = g0 || g1 || g2 || g3;

    wire [2:0] rel_cnt = {2'b00, r0} + {2'b00, r1} + {2'b00, r2} + {2'b00, r3};
    wire [2:0] pool_nx = {1'b0, pool} + rel_cnt - {2'b00, g_any};

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= 2'd2;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0; h3 <= 1'b0;
        end else begin
            pool <= pool_nx[1:0];
            h0 <= g0 || (h0 && !r0);
            h1 <= g1 || (h1 && !r1);
            h2 <= g2 || (h2 && !r2);
            h3 <= g3 || (h3 && !r3);
        end
    end

    // output port: lowest credited lane with valid data drives the shared bus
    always @(*) begin
        out_q   = 128'h0;
        out_v   = 1'b0;
        out_src = 2'd0;
        if (h0 && t0_out_v) begin
            out_q = t0_out_q; out_v = 1'b1; out_src = 2'd0;
        end else if (h1 && t1_out_v) begin
            out_q = t1_out_q; out_v = 1'b1; out_src = 2'd1;
        end else if (h2 && t2_out_v) begin
            out_q = t2_out_q; out_v = 1'b1; out_src = 2'd2;
        end else if (h3 && t3_out_v) begin
            out_q = t3_out_q; out_v = 1'b1; out_src = 2'd3;
        end
    end

    assign frame_v      = {t3_out_v, t2_out_v, t1_out_v, t0_out_v};
    assign out_tag_all  = {t3_out_tag, t2_out_tag, t1_out_tag, t0_out_tag};
    assign pipe_vld_all = {t3_pipe_vld, t2_pipe_vld, t1_pipe_vld, t0_pipe_vld};
    assign dbg_all      = {t3_dbg, t2_dbg, t1_dbg, t0_dbg};
    assign pool_o       = pool;
    assign hold_o       = {h3, h2, h1, h0};

    always @(posedge clk)
        assert (pool <= 2'd2);
endmodule


