    wire         t0_out_v, t1_out_v, t2_out_v, t3_out_v;
    wire [3:0]   t0_pipe_vld, t1_pipe_vld, t2_pipe_vld, t3_pipe_vld;
    wire [2:0]   t0_out_tag, t1_out_tag, t2_out_tag, t3_out_tag;
