    wire [3:0]   t0_cnt, t1_cnt, t2_cnt, t3_cnt;
    wire [2:0]   t0_rd_ptr, t1_rd_ptr, t2_rd_ptr, t3_rd_ptr;
    wire [2:0]   t0_st0_idx, t0_st1_idx, t0_st2_idx, t0_st3_idx;
    wire [2:0]   t1_st0_idx, t1_st1_idx, t1_st2_idx, t1_st3_idx;
    wire [2:0]   t2_st0_idx, t2_st1_idx, t2_st2_idx, t2_st3_idx;
    wire [2:0]   t3_st0_idx, t3_st1_idx, t3_st2_idx, t3_st3_idx;
    wire         t0_st0_v, t0_st1_v, t0_st2_v, t0_st3_v;
    wire         t1_st0_v, t1_st1_v, t1_st2_v, t1_st3_v;
    wire         t2_st0_v, t2_st1_v, t2_st2_v, t2_st3_v;
    wire         t3_st0_v, t3_st1_v, t3_st2_v, t3_st3_v;

    wire t0_en = en && h0;
    wire t1_en = en && h1;
    wire t2_en = en && h2;
    wire t3_en = en && h3;

    xbar_route_rom u0 (.clk(clk), .rst_n(rst_n), .en(t0_en), .start(start[0]), .stop(stop[0]),
        .out_q(t0_out_q), .out_v(t0_out_v), .pipe_vld(t0_pipe_vld), .out_tag(t0_out_tag), .dbg_stat(t0_dbg),
        .cnt_o(t0_cnt), .rd_ptr_o(t0_rd_ptr),
        .st0_idx_o(t0_st0_idx), .st0_v_o(t0_st0_v), .st1_idx_o(t0_st1_idx), .st1_v_o(t0_st1_v),
        .st2_idx_o(t0_st2_idx), .st2_v_o(t0_st2_v), .st3_idx_o(t0_st3_idx), .st3_v_o(t0_st3_v));

    xbar_route_rom u1 (.clk(clk), .rst_n(rst_n), .en(t1_en), .start(start[1]), .stop(stop[1]),
        .out_q(t1_out_q), .out_v(t1_out_v), .pipe_vld(t1_pipe_vld), .out_tag(t1_out_tag), .dbg_stat(t1_dbg),
        .cnt_o(t1_cnt), .rd_ptr_o(t1_rd_ptr),
        .st0_idx_o(t1_st0_idx), .st0_v_o(t1_st0_v), .st1_idx_o(t1_st1_idx), .st1_v_o(t1_st1_v),
        .st2_idx_o(t1_st2_idx), .st2_v_o(t1_st2_v), .st3_idx_o(t1_st3_idx), .st3_v_o(t1_st3_v));

    xbar_route_rom u2 (.clk(clk), .rst_n(rst_n), .en(t2_en), .start(start[2]), .stop(stop[2]),
        .out_q(t2_out_q), .out_v(t2_out_v), .pipe_vld(t2_pipe_vld), .out_tag(t2_out_tag), .dbg_stat(t2_dbg),
        .cnt_o(t2_cnt), .rd_ptr_o(t2_rd_ptr),
        .st0_idx_o(t2_st0_idx), .st0_v_o(t2_st0_v), .st1_idx_o(t2_st1_idx), .st1_v_o(t2_st1_v),
        .st2_idx_o(t2_st2_idx), .st2_v_o(t2_st2_v), .st3_idx_o(t2_st3_idx), .st3_v_o(t2_st3_v));

    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(t3_en), .start(start[3]), .stop(stop[3]),
        .out_q(t3_out_q), .out_v(t3_out_v), .pipe_vld(t3_pipe_vld), .out_tag(t3_out_tag), .dbg_stat(t3_dbg),
        .cnt_o(t3_cnt), .rd_ptr_o(t3_rd_ptr),
