module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
parameter DEPTH = 4,
parameter TRACE_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
output wire         head_cached,
output wire         trace_valid,
output reg  [W-1:0] trace_data,
output wire [2:0]   trace_kind,
output wire         trace_last,
output wire [$clog2(TRACE_DEPTH):0] trace_pending,
output wire         completion_wait
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam TRACE_ADDR_W = $clog2(TRACE_DEPTH);
    localparam TRACE_PTR_W = TRACE_ADDR_W + 1;
    localparam [TRACE_ADDR_W-1:0] TRACE_LAST_SLOT = TRACE_DEPTH - 1;
    localparam TRACE_WORDS = 8;
    localparam TRACE_WORD_W = $clog2(TRACE_WORDS);

    reg [W-1:0] trace_stage_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_bf_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_a_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_b_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_w_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_cycles_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_sum_mem [0:TRACE_DEPTH-1];
    reg [W-1:0] trace_dif_mem [0:TRACE_DEPTH-1];
    reg [TRACE_PTR_W-1:0] trace_wr = {TRACE_PTR_W{1'b0}};
    reg [TRACE_PTR_W-1:0] trace_rd = {TRACE_PTR_W{1'b0}};
    reg [W-1:0] trace_stage_r = 16'd0;
    reg [W-1:0] trace_bf_r = 16'd0;
    reg [W-1:0] trace_a_r = 16'd0;
    reg [W-1:0] trace_b_r = 16'd0;
    reg [W-1:0] trace_w_r = 16'd0;
    reg [W-1:0] trace_cycles_r = 16'd0;
    reg [W-1:0] trace_sum_r = 16'd0;
    reg [W-1:0] trace_dif_r = 16'd0;
    reg trace_active = 1'b0;
    reg [TRACE_WORD_W-1:0] trace_word = {TRACE_WORD_W{1'b0}};
    integer trace_init;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    wire [TRACE_ADDR_W-1:0] trace_head_slot = trace_rd[TRACE_ADDR_W-1:0];
    wire [TRACE_ADDR_W-1:0] trace_tail_slot =
        (trace_wr[TRACE_ADDR_W-1:0] == 0) ? TRACE_LAST_SLOT : trace_wr[TRACE_ADDR_W-1:0] - 1'b1;
    wire trace_empty = (trace_wr == trace_rd);
    wire trace_full = (trace_wr[TRACE_ADDR_W] != trace_rd[TRACE_ADDR_W]) &&
                      (trace_wr[TRACE_ADDR_W-1:0] == trace_rd[TRACE_ADDR_W-1:0]);
    wire trace_load = ce && !trace_active && !trace_empty;
    wire trace_beat = trace_active && out_ready;
    wire trace_pop = trace_beat && trace_last;
    assign trace_valid = trace_active;
    assign trace_kind = trace_word;
    assign trace_last = (trace_word == TRACE_WORDS - 1);
    assign completion_wait = busy && trace_full && (phase == lat_q - 16'd1);
    assign trace_pending = (trace_wr[TRACE_ADDR_W] == trace_rd[TRACE_ADDR_W]) ?
        ({1'b0, trace_wr[TRACE_ADDR_W-1:0]} - {1'b0, trace_rd[TRACE_ADDR_W-1:0]}) :
        (TRACE_DEPTH + {1'b0, trace_wr[TRACE_ADDR_W-1:0]} - {1'b0, trace_rd[TRACE_ADDR_W-1:0]});

    initial begin
        for (trace_init = 0; trace_init < TRACE_DEPTH; trace_init = trace_init + 1) begin
            trace_stage_mem[trace_init] = 16'd0;
            trace_bf_mem[trace_init] = 16'd0;
            trace_a_mem[trace_init] = 16'd0;
            trace_b_mem[trace_init] = 16'd0;
            trace_w_mem[trace_init] = 16'd0;
            trace_cycles_mem[trace_init] = 16'd0;
            trace_sum_mem[trace_init] = 16'd0;
            trace_dif_mem[trace_init] = 16'd0;
        end
    end

    always @(*) begin
        case (trace_word)
            3'd0: trace_data = trace_stage_r;
            3'd1: trace_data = trace_bf_r;
            3'd2: trace_data = trace_a_r;
            3'd3: trace_data = trace_b_r;
            3'd4: trace_data = trace_w_r;
            3'd5: trace_data = trace_cycles_r;
            3'd6: trace_data = trace_sum_r;
            3'd7: trace_data = trace_dif_r;
            default: trace_data = 16'd0;
        endcase
    end

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
wire retire = busy && ce && last && !trace_full;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (retire) begin
            trace_stage_mem[trace_wr[TRACE_ADDR_W-1:0]] <= stage;
            trace_bf_mem[trace_wr[TRACE_ADDR_W-1:0]] <= bf_idx;
            trace_a_mem[trace_wr[TRACE_ADDR_W-1:0]] <= a_r;
            trace_b_mem[trace_wr[TRACE_ADDR_W-1:0]] <= b_r;
            trace_w_mem[trace_wr[TRACE_ADDR_W-1:0]] <= w_r;
            trace_cycles_mem[trace_wr[TRACE_ADDR_W-1:0]] <= phase + 16'd1;
            trace_sum_mem[trace_wr[TRACE_ADDR_W-1:0]] <= sum_mod;
            trace_dif_mem[trace_wr[TRACE_ADDR_W-1:0]] <= dif_mod;
            if (trace_wr[TRACE_ADDR_W-1:0] == TRACE_LAST_SLOT)
                trace_wr <= {!trace_wr[TRACE_ADDR_W], {TRACE_ADDR_W{1'b0}}};
            else
                trace_wr <= trace_wr + 1'b1;
        end
        if (trace_pop) begin
            if (trace_rd[TRACE_ADDR_W-1:0] == TRACE_LAST_SLOT)
                trace_rd <= {!trace_rd[TRACE_ADDR_W], {TRACE_ADDR_W{1'b0}}};
            else
                trace_rd <= trace_rd + 1'b1;
        end
    end

    always @(posedge clk) begin
        if (trace_load) begin
            trace_stage_r <= trace_stage_mem[trace_head_slot];
            trace_bf_r <= trace_bf_mem[trace_head_slot];
            trace_a_r <= trace_a_mem[trace_head_slot];
            trace_b_r <= trace_b_mem[trace_head_slot];
            trace_w_r <= trace_w_mem[trace_head_slot];
            trace_cycles_r <= trace_cycles_mem[trace_head_slot];
            trace_sum_r <= trace_sum_mem[trace_head_slot];
            trace_dif_r <= trace_dif_mem[trace_head_slot];
            trace_active <= 1'b1;
            trace_word <= {TRACE_WORD_W{1'b0}};
        end else if (trace_beat) begin
            if (trace_pop) begin
                trace_active <= 1'b0;
                trace_word <= {TRACE_WORD_W{1'b0}};
            end else begin
                trace_word <= trace_word + 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (trace_active)
            assert ((trace_cycles_r != 16'd0) &&
                    (trace_stage_r < STAGES) && (trace_bf_r < NBF) &&
                    (!(out_valid && (trace_pending == 1)) ||
                     ((trace_sum_r == out_a) && (trace_dif_r == out_b))));
    end

    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
end else if (busy && ce && (!last || !trace_full)) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

