module ntt_phase_dispatch #(
    parameter W = 16,
    parameter PROFILES = 4,
    parameter MAX_BURST = 4
) (
    input  wire clk,
    input  wire cfg_valid,
    output wire cfg_ready,
    input  wire [W-1:0] cfg_data,
    input  wire [W-1:0] profile_select,
    input  wire start,
    input  wire run,
    input  wire finish,
    input  wire [W-1:0] remaining,
    input  wire [W-1:0] launch_latency,
    output reg  [W-1:0] step = 16'd0,
    output reg  [W-1:0] quantum = 16'd1,
    output wire [W*PROFILES-1:0] profiles,
    output reg  [1:0] cfg_state = 2'd0,
    output reg  [$clog2(PROFILES)-1:0] cfg_index = 0,
    output reg  [W-1:0] cfg_pending = 16'd0,
    output reg  [W-1:0] cfg_prepared = 16'd1,
    output wire cfg_apply
);
    localparam INDEX_W = $clog2(PROFILES);
    localparam [INDEX_W-1:0] LAST_PROFILE = PROFILES - 1;
    reg [W-1:0] cap [0:PROFILES-1];
    wire [INDEX_W-1:0] selected = profile_select % PROFILES;
    integer init_profile;
    initial begin
        for (init_profile = 0; init_profile < PROFILES; init_profile = init_profile + 1) begin
            cap[init_profile] = 16'd1;
        end
    end
    genvar p;
    generate
        for (p = 0; p < PROFILES; p = p + 1) begin: expose_profiles
            assign profiles[p*W +: W] = cap[p];
        end
    endgenerate
    assign cfg_ready = (cfg_state == 2'd0);
    assign cfg_apply = (cfg_state == 2'd2);

    function [W-1:0] choose_step;
        input [W-1:0] left;
        input [W-1:0] limit;
        begin
            if (left <= 16'd1)
                choose_step = 16'd1;
            else if (left - 16'd1 < limit)
                choose_step = left - 16'd1;
            else
                choose_step = limit;
        end
    endfunction

    always @(posedge clk) begin
        case (cfg_state)
            2'd0: begin
                if (cfg_valid && cfg_ready) begin
                    cfg_pending <= cfg_data;
                    cfg_state <= 2'd1;
                end
            end
            2'd1: begin
                if (cfg_pending == 16'd0)
                    cfg_prepared <= 16'd1;
                else if (cfg_pending > MAX_BURST)
                    cfg_prepared <= MAX_BURST;
                else
                    cfg_prepared <= cfg_pending;
                cfg_state <= 2'd2;
            end
            2'd2: begin
                cap[cfg_index] <= cfg_prepared;
                if (cfg_index == LAST_PROFILE)
                    cfg_index <= {INDEX_W{1'b0}};
                else
                    cfg_index <= cfg_index + 1'b1;
                cfg_state <= 2'd0;
            end
            default: cfg_state <= 2'd0;
        endcase
    end

    always @(posedge clk) begin
        if (start) begin
            quantum <= cap[selected];
            step <= choose_step(launch_latency, cap[selected]);
        end else if (finish) begin
            step <= 16'd0;
        end else if (run) begin
            step <= choose_step(remaining - step, quantum);
        end
    end
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4,
    parameter BURST_PROFILES = 4,
    parameter MAX_BURST = 4,
    parameter PEER_DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached,
    output wire         cfg_ready,
    output wire         cfg_busy,
    output wire [W-1:0] burst_step,
    output wire [W*BURST_PROFILES-1:0] burst_profiles,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_a,
    input  wire [W-1:0] peer_b,
    input  wire [W-1:0] peer_w,
    input  wire [W-1:0] peer_latency,
    output wire [$clog2(PEER_DEPTH):0] peer_queued,
    output reg          peer_active = 1'b0,
    output reg  [W-1:0] peer_phase = 16'd0,
    output reg  [W-1:0] peer_remaining = 16'd0,
    output reg          out_owner = 1'b0
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;
    localparam CHANNELS = 2;
    localparam LANE_W = $clog2(CHANNELS);
    localparam PEER_ADDR_W = $clog2(PEER_DEPTH);
    localparam PEER_PTR_W = PEER_ADDR_W + 1;
    localparam [PEER_ADDR_W-1:0] PEER_LAST_SLOT = PEER_DEPTH - 1;
    localparam FLIGHT_W = $clog2(DEPTH + PEER_DEPTH + 2);

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    reg [W-1:0] peer_q_a [0:PEER_DEPTH-1];
    reg [W-1:0] peer_q_b [0:PEER_DEPTH-1];
    reg [W-1:0] peer_q_w [0:PEER_DEPTH-1];
    reg [W-1:0] peer_q_lat [0:PEER_DEPTH-1];
    reg [PEER_PTR_W-1:0] peer_wr = {PEER_PTR_W{1'b0}};
    reg [PEER_PTR_W-1:0] peer_rd = {PEER_PTR_W{1'b0}};
    reg [LANE_W-1:0] next_lane = {LANE_W{1'b0}};
    wire [CHANNELS-1:0] request;
    reg [CHANNELS-1:0] grant;
    integer init_peer;
    wire [PEER_ADDR_W-1:0] peer_head = peer_rd[PEER_ADDR_W-1:0];
    wire peer_empty = (peer_wr == peer_rd);
    wire peer_full = (peer_wr[PEER_ADDR_W] != peer_rd[PEER_ADDR_W]) &&
                     (peer_wr[PEER_ADDR_W-1:0] == peer_rd[PEER_ADDR_W-1:0]);
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    initial begin
        for (init_peer = 0; init_peer < PEER_DEPTH; init_peer = init_peer + 1) begin
            peer_q_a[init_peer] = 16'd0;
            peer_q_b[init_peer] = 16'd0;
            peer_q_w[init_peer] = 16'd0;
            peer_q_lat[init_peer] = 16'd0;
        end
    end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;
    assign peer_ready = !peer_full;
    assign peer_queued = (peer_wr[PEER_ADDR_W] == peer_rd[PEER_ADDR_W]) ?
        ({1'b0, peer_wr[PEER_ADDR_W-1:0]} - {1'b0, peer_rd[PEER_ADDR_W-1:0]}) :
        (PEER_DEPTH + {1'b0, peer_wr[PEER_ADDR_W-1:0]} - {1'b0, peer_rd[PEER_ADDR_W-1:0]});
    wire peer_accept = peer_valid && peer_ready;
    wire peer_deliver = out_valid && out_ready && out_owner;
    wire [FLIGHT_W-1:0] held_items = {1'b0, queued} + {1'b0, peer_queued} +
        ((out_valid && !out_owner) ? 1'b1 : 1'b0);

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = grant[0];
    wire peer_last = (peer_phase == peer_q_lat[peer_head] - 16'd1);
    assign request[0] = busy && ce && last;
    assign request[1] = peer_active && ce && peer_last;
    always @(*) begin
        grant = {CHANNELS{1'b0}};
        if (!out_valid) begin
            if (request[0] && request[1])
                grant[next_lane] = 1'b1;
            else if (request[0])
                grant[0] = 1'b1;
            else if (request[1])
                grant[1] = 1'b1;
        end
    end
    always @(posedge clk) begin
        if (grant[0]) next_lane <= 1'b1;
        else if (grant[1]) next_lane <= 1'b0;
    end
    wire [W-1:0] burst_quantum;
    wire [1:0] cfg_state;
    wire [$clog2(BURST_PROFILES)-1:0] cfg_write_index;
    wire [W-1:0] cfg_pending;
    wire [W-1:0] cfg_prepared;
    wire cfg_apply;
    assign cfg_busy = (cfg_state != 2'd0);

    ntt_phase_dispatch #(
        .W(W), .PROFILES(BURST_PROFILES), .MAX_BURST(MAX_BURST)
    ) phase_dispatch (
        .clk(clk), .cfg_valid(load_cfg), .cfg_ready(cfg_ready),
        .cfg_data(cfg_lat), .profile_select(stage),
        .start(start), .run(busy && ce && !last), .finish(retire),
        .remaining(cd), .launch_latency(lat_q),
        .step(burst_step), .quantum(burst_quantum),
        .profiles(burst_profiles), .cfg_state(cfg_state),
        .cfg_index(cfg_write_index), .cfg_pending(cfg_pending),
        .cfg_prepared(cfg_prepared), .cfg_apply(cfg_apply)
    );

    wire [W-1:0] shared_a = grant[1] ? peer_q_a[peer_head] : a_r;
    wire [W-1:0] shared_b = grant[1] ? peer_q_b[peer_head] : b_r;
    wire [W-1:0] shared_w = grant[1] ? peer_q_w[peer_head] : w_r;
    wire [31:0] prod = shared_w * shared_b;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, shared_a} + {1'b0, t};
    wire [16:0] dif = {1'b0, shared_a} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (peer_accept) begin
            peer_q_a[peer_wr[PEER_ADDR_W-1:0]] <= peer_a;
            peer_q_b[peer_wr[PEER_ADDR_W-1:0]] <= peer_b;
            peer_q_w[peer_wr[PEER_ADDR_W-1:0]] <= peer_w;
            peer_q_lat[peer_wr[PEER_ADDR_W-1:0]] <=
                (peer_latency == 16'd0) ? 16'd1 : peer_latency;
            if (peer_wr[PEER_ADDR_W-1:0] == PEER_LAST_SLOT)
                peer_wr <= {!peer_wr[PEER_ADDR_W], {PEER_ADDR_W{1'b0}}};
            else
                peer_wr <= peer_wr + 1'b1;
        end
        if (peer_deliver) begin
            if (peer_rd[PEER_ADDR_W-1:0] == PEER_LAST_SLOT)
                peer_rd <= {!peer_rd[PEER_ADDR_W], {PEER_ADDR_W{1'b0}}};
            else
                peer_rd <= peer_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (peer_deliver) begin
            peer_active <= 1'b0;
            peer_remaining <= 16'd0;
            peer_phase <= 16'd0;
        end else if (ce) begin
            if (!peer_active && !peer_empty) begin
                peer_active <= 1'b1;
                peer_remaining <= peer_q_lat[peer_head];
                peer_phase <= 16'd0;
            end else if (peer_active && !peer_last) begin
                peer_remaining <= peer_remaining - 16'd1;
                peer_phase <= peer_phase + 16'd1;
            end
        end
    end
    always @(posedge clk) begin
        if (|grant) begin
            out_valid <= 1'b1;
            out_owner <= grant[1];
            out_a <= sum_mod;
            out_b <= dif_mod;
        end else if (out_valid && out_ready) begin
            out_valid <= 1'b0;
        end
    end
    always @(posedge clk) begin
        if (out_valid && out_owner)
            assert (peer_remaining == 16'd1);
    end
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (cfg_apply) lat_cfg <= cfg_pending;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce && (!last || grant[0])) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - burst_step;
                phase <= phase + burst_step;
            end
        end
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

