        lookup_hit = 1'b0;
        for (j = 0; j < DEPTH; j = j + 1)
            if (valid[j] && tag_mem[j] == lookup_addr)
                lookup_hit = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= {DEPTH{1'b0}};
            wr_ptr <= {AW{1'b0}};
            rd_ptr <= {AW{1'b0}};
            count <= {(AW+1){1'b0}};
            next_fetch <= 64'd0;
            head_addr <= 64'd0;
            fetch_seen <= 64'd0;
            consume_seen <= 64'd0;
            before_flush <= 1'b1;
            out_valid <= 1'b0;
            out_tag <= 64'd0;
            out_desc <= 64'd0;
        end else if (step) begin
            if (flush) begin
                valid <= {DEPTH{1'b0}};
                count <= {(AW+1){1'b0}};
                rd_ptr <= wr_ptr;
                head_addr <= next_fetch;
                out_valid <= 1'b0;
                before_flush <= 1'b0;
            end else begin
                out_valid <= do_consume;
                if (do_fetch) begin
                    tag_mem[wr_ptr]  <= next_fetch;
                    data_mem[wr_ptr] <= desc_in;
                    valid[wr_ptr] <= 1'b1;
                    wr_ptr <= wr_ptr + 1'b1;
                    next_fetch <= next_fetch + 64'd1;
                    fetch_seen <= fetch_seen + 64'd1;
                end
                if (do_consume) begin
                    valid[rd_ptr] <= 1'b0;
                    rd_ptr <= rd_ptr + 1'b1;
                    head_addr <= head_addr + 64'd1;
                    consume_seen <= consume_seen + 64'd1;
                    out_tag <= head_addr;
                    out_desc <= data_mem[rd_ptr];
                end
                case ({do_fetch, do_consume})
                    2'b10:   count <= count + 1'b1;
                    2'b01:   count <= count - 1'b1;
