        uncorr_count = 64'd0;
        scrub_addr   = {AW{1'b0}};
        for (k = 0; k < ENTRIES; k = k + 1) begin
            mem_data[k] = {DW{1'b0}};
            mem_chk[k]  = {CW{1'b0}};
        end
    end

    function [CW-1:0] hcode;
        input [DW-1:0] d;
        integer i;
        begin
            hcode = {CW{1'b0}};
            for (i = 0; i < DW; i = i + 1)
                if (d[i]) hcode = hcode ^ (i + 1);
        end
    endfunction

    wire [CW-1:0] syndrome = line_chk ^ hcode(line_data);

    always @(posedge clk) begin
        if (!rst && ce) begin
            if (state == WRITE) begin
                mem_data[scrub_addr] <= line_data;
                mem_chk[scrub_addr]  <= hcode(line_data);
            end else if (fill_en) begin
                mem_data[fill_addr] <= fill_data;
                mem_chk[fill_addr]  <= fill_chk;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= IDLE;
            deadline     <= 64'd0;
            timer        <= INTERVAL;
            scrub_addr   <= {AW{1'b0}};
            corr_count   <= 64'd0;
            uncorr_count <= 64'd0;
            line_data    <= {DW{1'b0}};
            line_chk     <= {CW{1'b0}};
        end else if (ce) begin
            case (state)
                IDLE: begin
                    if (timer == 64'd0) begin
                        state    <= READ;
                        deadline <= BUDGET;
                        timer    <= INTERVAL;
                    end else begin
                        timer <= timer - 64'd1;
                    end
                end
                READ: begin
                    line_data <= mem_data[scrub_addr];
                    line_chk  <= mem_chk[scrub_addr];
                    deadline  <= deadline - 64'd1;
                    state     <= CHECK;
                end
                CHECK: begin
                    deadline <= deadline - 64'd1;
                    if (syndrome == {CW{1'b0}}) begin
                        state <= LOG;
                    end else if (syndrome <= DW) begin
                        line_data <= line_data ^ ({{(DW-1){1'b0}}, 1'b1} << (syndrome - 7'd1));
                        state     <= WRITE;
                    end else begin
                        uncorr_count <= uncorr_count + 64'd1;
                        state        <= LOG;
                    end
                end
                WRITE: begin
                    deadline   <= deadline - 64'd1;
                    corr_count <= corr_count + 64'd1;
                    state      <= LOG;
                end
                LOG: begin
                    deadline   <= 64'd0;
                    scrub_addr <= scrub_addr + 1'b1;
                    state      <= IDLE;
                end
                default: begin
                    deadline <= 64'd0;
                    state    <= IDLE;
                end
            endcase
        end
    end

    wire expired = (deadline == 64'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(expired))
            assert (state == IDLE);
endmodule

