  assign o_lnch_hist = {lnch_hist_vld, lnch_hist};
 assign o_gov_rdy = gov_rdy;
 assign o_gov_irq = gov_irq;
 assign o_gov_stat = {gov_pend, gov_forced, gov_go, gov_settle, gov_age, gov_stall, gov_why, gov_credits, gov_debt, gov_cred_min, gov_refill};
 assign o_gov_mon = {gov_waste, gov_stall_max, gov_cancel, gov_force_cnt, gov_evt, gov_since};
 assign o_gov_log = {gov_log_vld, gov_log, gov_log_aux, gov_log_cred};
 assign o_gov_slot = {gov_slot_seen, gov_slot_cnt, gov_stab, gov_lat, gov_rsn};
 assign o_gov_burst = {gov_drift_max, gov_burst_max, gov_epoch};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

