        .clk           (clk),
        .rst           (rst),
.i_ce          (up_ce),
        .i_k           (i_k),
        .i_kcode       (i_kcode),
        .i_phase       (phase),
        .i_rd          (o_rd),
        .i_sof         (do_sof),
        .i_eof         (do_eof),
        .i_data_sym    (do_data),
        .i_cur_len     (cur_len),
        .o_suspend     (pre_suspend),
        .o_resume      (pre_resume),
        .o_ctl_sym     (pre_sym),
        .o_rest_len    (pre_rest_len),
        .o_depth       (pre_depth),
        .o_ready       (o_pre_ready),
        .o_preempt_cnt (o_pre_cnt),
        .o_resume_cnt  (o_pre_resume_cnt),
        .o_refuse_cnt  (o_pre_refuse_cnt),
