module rs_exec_watchdog (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        alloc,
    input  wire [2:0]  alloc_idx,
    input  wire [31:0] alloc_tag1,
    input  wire [31:0] alloc_tag2,
    input  wire [31:0] alloc_val1,
    input  wire [31:0] alloc_val2,
    input  wire        alloc_rdy1,
    input  wire        alloc_rdy2,
    input  wire        cdb_valid,
    input  wire [31:0] cdb_tag,
    input  wire [31:0] cdb_val,
    output reg  [31:0] result
);
    // ---- 8-entry reservation station -------------------------------
    reg [7:0]  rs_valid;
    reg [7:0]  rs_rdy1;
    reg [7:0]  rs_rdy2;
    reg [31:0] rs_tag1 [0:7];
    reg [31:0] rs_tag2 [0:7];
    reg [31:0] rs_val1 [0:7];
    reg [31:0] rs_val2 [0:7];

    // ---- fixed-latency execute slot (the tracked request) ----------
    reg        exec_busy;   // window register: set on dispatch, cleared on writeback
    reg [31:0] stage;       // 0,1,2 inside the window
    reg [31:0] deadline;    // bounded-response countdown
    reg [31:0] exec_a;
    reg [31:0] exec_b;

    integer i;

    initial begin
        rs_valid  = 8'h00;
        rs_rdy1   = 8'h00;
        rs_rdy2   = 8'h00;
        exec_busy = 1'b0;
        stage     = 32'd0;
        deadline  = 32'd0;
        exec_a    = 32'd0;
        exec_b    = 32'd0;
        result    = 32'd0;
        for (i = 0; i < 8; i = i + 1) begin
            rs_tag1[i] = 32'd0;
            rs_tag2[i] = 32'd0;
            rs_val1[i] = 32'd0;
            rs_val2[i] = 32'd0;
        end
    end

    // ---- pick lowest-index entry whose operands have all arrived ----
    reg        sel_valid;
    reg [2:0]  sel_idx;
    always @(*) begin
        sel_valid = 1'b0;
        sel_idx   = 3'd0;
        for (i = 7; i >= 0; i = i - 1) begin
            if (rs_valid[i] && rs_rdy1[i] && rs_rdy2[i]) begin
                sel_valid = 1'b1;
                sel_idx   = i[2:0];
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            rs_valid  <= 8'h00;
            rs_rdy1   <= 8'h00;
            rs_rdy2   <= 8'h00;
            exec_busy <= 1'b0;
            stage     <= 32'd0;
            deadline  <= 32'd0;
        end else if (ce) begin
            // common data bus wakeup of waiting operands
            for (i = 0; i < 8; i = i + 1) begin
                if (rs_valid[i] && !rs_rdy1[i] && cdb_valid && (rs_tag1[i] == cdb_tag)) begin
                    rs_rdy1[i] <= 1'b1;
                    rs_val1[i] <= cdb_val;
                end
                if (rs_valid[i] && !rs_rdy2[i] && cdb_valid && (rs_tag2[i] == cdb_tag)) begin
                    rs_rdy2[i] <= 1'b1;
                    rs_val2[i] <= cdb_val;
                end
            end

            // allocate a new waiting operation into a free slot
            if (alloc && !rs_valid[alloc_idx]) begin
                rs_valid[alloc_idx] <= 1'b1;
                rs_rdy1[alloc_idx]  <= alloc_rdy1;
                rs_rdy2[alloc_idx]  <= alloc_rdy2;
                rs_tag1[alloc_idx]  <= alloc_tag1;
                rs_tag2[alloc_idx]  <= alloc_tag2;
                rs_val1[alloc_idx]  <= alloc_val1;
                rs_val2[alloc_idx]  <= alloc_val2;
            end

            // dispatch / execute
            if (!exec_busy) begin
                if (sel_valid) begin
                    exec_busy           <= 1'b1;
                    stage               <= 32'd0;
                    deadline            <= 32'd5;
                    exec_a              <= rs_val1[sel_idx];
                    exec_b              <= rs_val2[sel_idx];
                    rs_valid[sel_idx]   <= 1'b0;
                    rs_rdy1[sel_idx]    <= 1'b0;
                    rs_rdy2[sel_idx]    <= 1'b0;
                end
            end else begin
                if (stage == 32'd2) begin
                    exec_busy <= 1'b0;
                    stage     <= 32'd0;
                    deadline  <= 32'd0;
                    result    <= exec_a + exec_b;
                end else begin
                    stage    <= stage + 32'd1;
                    deadline <= deadline - 32'd1;
                end
            end
        end
    end

    // P: the countdown never expires while the dispatched op is outstanding
    always @(posedge clk)
        assert (!exec_busy || (deadline != 32'd0));
endmodule

