                avg  <= avg_next;
                cnt  <= cnt - 32'd1;
                busy <= (cnt != 32'd2);
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $past(busy))
            assert ($past(cnt) != 32'd0);
