module deq_chain (
    input wire clk,
    input wire rst,
    input wire i_push,
    input wire i_pop,
    input wire i_flush,
    input wire [15:0] i_data,
    output wire o_full,
    output wire o_empty,
    output wire [15:0] o_head,
    output wire [15:0] o_tail,
    output wire [15:0] o_count,
    output wire [1:0] o_st
);
    localparam [15:0] DEPTH_M1 = 16'd23;

    reg [15:0] mem [0:23];
    reg [4:0] head = 5'd0;
    reg [4:0] tail = 5'd0;
    reg [15:0] count = 16'd0;
    reg [1:0] st = 2'd0;
    reg seen_arm = 1'b0;
    reg seen_start = 1'b0;
    reg before_flush = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    wire do_push = i_push && !o_full;
    wire do_pop = i_pop && !o_empty;
    wire net_push = do_push && !do_pop;
    wire net_pop = do_pop && !do_push;

    assign o_full = (count == 16'd24);
    assign o_empty = (count == 16'd0);
    assign o_head = mem[head];
    assign o_tail = mem[tail];
    assign o_count = count;
    assign o_st = st;

    always @(posedge clk) begin
        if (rst) begin
            head <= 5'd0;
            tail <= 5'd0;
            count <= 16'd0;
            st <= 2'd0;
            seen_arm <= 1'b0;
            seen_start <= 1'b0;
            before_flush <= 1'b1;
        end else if (i_flush) begin
            head <= 5'd0;
            tail <= 5'd0;
            count <= 16'd0;
            st <= 2'd0;
            seen_arm <= 1'b0;
            seen_start <= 1'b0;
            before_flush <= 1'b0;
        end else begin
            if (net_push) begin
                mem[tail] <= i_data;
                tail <= tail + 5'd1;
            end else if (net_pop) begin
                head <= head + 5'd1;
            end
            case (st)
                2'd0: if (do_push) begin
                          st <= 2'd1;
                          seen_arm <= 1'b1;
                      end
                2'd1: if (do_pop) begin
                          st <= 2'd2;
                          seen_start <= 1'b1;
                      end
                2'd2: if (do_push) st <= 2'd2;
                default: ;
            endcase
            case ({do_push, do_pop})
                2'b10: if (count != 16'd24) count <= count + 16'd1;
                2'b01: if (count != 16'd0) count <= count - 16'd1;
                default: ;
            endcase
        end
    end

    always @(posedge clk)
        if (before_flush && st == 2'd2)
            assert (seen_start && seen_arm);
