        res       = 32'd0;
        a_res     = 2'd0;
        b_res     = 2'd0;
        r_res     = 2'd0;
        mismatch  = 1'b0;
        phase     = IDLE;
        saw_arm   = 1'b0;
        saw_start = 1'b0;
        win       = 1'b0;
        pv        = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            op_a      <= 32'd0;
            op_b      <= 32'd0;
            prod      <= 32'd0;
            res       <= 32'd0;
            a_res     <= 2'd0;
            b_res     <= 2'd0;
            r_res     <= 2'd0;
            mismatch  <= 1'b0;
            phase     <= IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
            win       <= 1'b0;
        end else if (ce) begin
            if (q_open)
                win <= 1'b1;
            else if (r_close)
                win <= 1'b0;
            case (phase)
                IDLE: begin
                    if (arm) begin
                        op_a    <= opa;
                        op_b    <= opb;
                        a_res   <= opa % 32'd3;
                        b_res   <= opb % 32'd3;
                        saw_arm <= 1'b1;
                        phase   <= ARMED;
                    end
                end
                ARMED: begin
                    if (start) begin
                        saw_start <= 1'b1;
                        phase     <= RUN;
                    end
                end
                RUN: begin
                    prod <= op_a * op_b;
                    res  <= prod;
                    r_res <= prod % 32'd3;
