        if (rst) begin
            stage      <= S_IDLE;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            lane_ptr   <= 2'd0;
            marker_cnt <= 16'd1;
        end else if (ce) begin
            case (stage)
                S_IDLE: begin
                    if (arm) begin
                        stage      <= S_ARMED;
                        seen_arm   <= 1'b1;
                        lane_ptr   <= 2'd0;
                        marker_cnt <= 16'd1;
                    end
                end
                S_ARMED: begin
                    if (start) begin
                        stage      <= S_RUN;
                        seen_start <= 1'b1;
                    end
                end
                S_RUN: begin
                    case (lane_ptr)
                        2'd0: lane0_out <= din;
                        2'd1: lane1_out <= din;
                        2'd2: lane2_out <= din;
                        2'd3: lane3_out <= din;
                    endcase
                    lane_ptr <= lane_ptr + 2'd1;
                    if (marker_cnt == 16'd1) begin
                        marker_cnt <= 16'd4;
                        stage      <= S_MARKER;
                    end else begin
                        marker_cnt <= marker_cnt - 16'd1;
                    end
                end
                S_MARKER: begin
                    case (lane_ptr)
                        2'd0: lane0_out <= 16'hAA55;
                        2'd1: lane1_out <= 16'h55AA;
                        2'd2: lane2_out <= 16'hA5A5;
                        2'd3: lane3_out <= 16'h5A5A;
