module usb_irq_agg (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_arm,
    input  wire        i_disarm,
    input  wire [3:0]  src,
    input  wire        i_ack_all,
    input  wire [31:0] i_mask_wr,
    input  wire        i_mask_we,
    output reg         irq,
    output reg  [31:0] masked_o
);
    // ---- status aggregator state ----
    reg [31:0] raw    = 32'h00000000;
    reg [31:0] mask   = 32'hFFFFFFFF;
    reg [31:0] masked = 32'h00000000;

    // ---- precedence shadow: a load was posted at some point ----
    reg seen_load = 1'b0;

    // ---- window register: armed after Q (i_arm) until R (i_disarm, may never come) ----
    reg armed = 1'b0;

    initial begin
        irq      = 1'b0;
        masked_o = 32'h00000000;
    end

    // source events: SOF, Rx packet, Tx packet, bus reset
    wire [31:0] src_vec = {31'd0, src[3], src[2], src[1], src[0]};

    always @(posedge clk) begin
        if (i_ce) begin
            // raw status is OR-combined source events
            raw       <= raw | src_vec;
            masked    <= (raw | src_vec) & mask;
            irq       <= ((raw | src_vec) & mask) != 32'h00000000;
            masked_o  <= (raw | src_vec) & mask;

            if (src_vec != 32'h00000000)
                seen_load <= 1'b1;

            if (i_ack_all) begin
                raw       <= 32'h00000000;
                masked    <= 32'h00000000;
                irq       <= 1'b0;
            end

            if (i_mask_we)
                mask <= i_mask_wr;

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Precedence, in the "after arm until disarm" window:
    // a nonzero masked status can only be observed if a source event was
    // recorded into the raw status earlier.
    always @(posedge clk)
        if (armed && (masked != 32'h00000000))
            assert (seen_load);
endmodule

