    reg       ack_seen;  // marks the first acknowledge, scopes the check

    initial begin
        pend     = 4'b0000;
        active_lo = 4'b0000;
        active_hi = 4'b0000;
        chain_lo  = 1'b0;
        chain_hi  = 1'b0;
        ack_seen = 1'b1;
    end

    wire [3:0] any = pend & ~active_lo & ~active_hi;
    wire [3:0] lo  = any & 4'b0011;
    wire [3:0] hi  = any & 4'b1100;
    wire preempts = (hi != 4'b0000) && (active_lo != 4'b0000);

    always @(posedge clk) begin
        if (ce) begin
            if (i_ack) begin
                // acknowledge retires the running handler; a high-group
                // acknowledge also clears the chain flag of the handler
                // it had preempted
                if (active_hi != 4'b0000) begin
                    active_hi <= 4'b0000;
                    chain_hi  <= 1'b0;
                end else if (active_lo != 4'b0000) begin
                    active_lo <= 4'b0000;
                    chain_lo  <= 1'b0;
                end
                ack_seen <= 1'b0;
            end else begin
                if (pend != 4'b0000) begin
                    if (preempts) begin
                        // high-group handler: restore, so clear the low chain
                        active_hi <= hi;
                        pend      <= pend & ~hi;
                        chain_hi  <= 1'b1;
                        chain_lo  <= 1'b0;
                    end else if (lo != 4'b0000) begin
                        if (i_chain) begin
                            active_lo <= lo;
                            pend      <= pend & ~lo;
                            chain_lo  <= 1'b1;
                        end else begin
                            active_lo <= lo;
                            pend      <= pend & ~lo;
                            chain_lo  <= 1'b0;
                        end
                    end
                end
            end
        end
    end

