    assign o_chain    = (active_hi != 4'b0000) ? chain_hi : chain_lo;
    assign o_pend     = pend;
    assign o_preempt  = preempts;

    // Before the first acknowledge: whenever a handler runs, it was the one
    // that was just lifted from the pending bitmap, and the pending bitmap
    // is empty.
    always @(posedge clk)
        if (ack_seen && (active_lo != 4'b0000))
            assert ((pend == 4'b0000) && (active_lo == (active_lo & ~(active_lo - 4'd1))));

    always @(posedge clk)
        if (ack_seen && (active_hi != 4'b0000))
            assert ((pend == 4'b0000) && (active_hi == (active_hi & ~(active_hi - 4'd1))));
endmodule


