module wb2axi_wr_bridge (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_wr,
    input  wire        i_wdata_valid,
    input  wire [15:0] i_wdata,
    input  wire        i_resp_valid,
    input  wire        i_resp_ok,
    output wire        o_wb_ack,
    output wire        o_aw_valid,
    output wire [15:0] o_aw_addr,
    output wire        o_w_valid,
    output wire [15:0] o_w_data,
    output wire        o_b_ready,
    output wire        o_busy
);
    localparam [1:0] PH_IDLE   = 2'd0;
    localparam [1:0] PH_AWVALID = 2'd1;
    localparam [1:0] PH_W       = 2'd2;
    localparam [1:0] PH_BREADY  = 2'd3;

    reg [1:0]  phase;
    reg        aw_valid;
    reg [15:0] aw_addr;
    reg        w_last;
    reg [3:0]  w_cnt;
    reg [15:0] w_data_q;
    reg        b_valid;
    reg        b_ok;
    reg        win;

    initial begin
        phase = PH_IDLE;
        aw_valid = 1'b0;
        aw_addr = 16'd0;
        w_last = 1'b0;
        w_cnt = 4'd0;
        w_data_q = 16'd0;
        b_valid = 1'b0;
        b_ok = 1'b0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE;
            aw_valid <= 1'b0;
            w_last <= 1'b0;
            w_cnt <= 4'd0;
            b_valid <= 1'b0;
            win <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (i_wr) begin
                        phase <= PH_AWVALID;
                        aw_valid <= 1'b1;
                        aw_addr <= 16'd0;
                        w_cnt <= 4'd0;
                        w_last <= 1'b0;
                        win <= 1'b1;
                    end
                end
                PH_AWVALID: begin
                    if (i_wdata_valid) begin
                        w_data_q <= i_wdata;
                        w_cnt <= 4'd1;
                        w_last <= 1'b1;
                        phase <= PH_W;
                    end
                end
                PH_W: begin
                    if (i_wdata_valid) begin
                        w_cnt <= w_cnt + 4'd1;
                    end
                    if (w_last) begin
                        w_last <= 1'b0;
                        phase <= PH_BREADY;
                    end
                end
                PH_BREADY: begin
                    if (i_resp_valid) begin
                        b_valid <= 1'b1;
                        b_ok <= i_resp_ok;
                        phase <= PH_IDLE;
                        win <= 1'b0;
                    end
                end
                default: begin
                    phase <= PH_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    assign o_wb_ack   = (phase == PH_W) && i_wdata_valid;
    assign o_aw_valid = aw_valid;
    assign o_aw_addr  = aw_addr;
    assign o_w_valid  = (phase == PH_W) || (phase == PH_AWVALID && i_wdata_valid);
    assign o_w_data   = w_data_q;
    assign o_b_ready  = (phase == PH_BREADY);
    assign o_busy     = (phase != PH_IDLE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && phase == 2'd2)
            assert (w_cnt == 4'd1);
endmodule


