    input  wire       rst,
    input  wire       ce,
    input  wire       issue,
    input  wire [7:0] opnd,
    input  wire [7:0] tag,
    input  wire       in_valid,
    input  wire [7:0] in_tag,
    input  wire       ret_valid,
    output reg  [7:0] result,
    output reg        busy
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_ARMED = 2'd1;
    localparam [1:0] S_RUN   = 2'd2;
    localparam [1:0] S_FIN   = 2'd3;

    reg [1:0] stage;
    reg       armed_seen;
    reg       started_seen;
    reg [7:0] opnd_q;
    reg [7:0] tag_q;
    reg [7:0] src_q;
    reg       src_ready;
    reg       busy_r;
    reg       pv;

    initial begin
        stage = S_IDLE;
        armed_seen = 1'b0;
        started_seen = 1'b0;
        opnd_q = 8'd0;
        tag_q = 8'd0;
        src_q = 8'd0;
        src_ready = 1'b0;
        busy_r = 1'b0;
        pv = 1'b0;
        result = 8'd0;
        busy = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            stage <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            opnd_q <= 8'd0;
            tag_q <= 8'd0;
            src_q <= 8'd0;
            src_ready <= 1'b0;
            busy_r <= 1'b0;
            result <= 8'd0;
        end else if (ce) begin
            case (stage)
                S_IDLE: begin
                    if (issue) begin
                        opnd_q <= opnd;
                        tag_q <= tag;
                        stage <= S_ARMED;
                        armed_seen <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (in_valid && in_tag == tag_q) begin
                        src_q <= 8'd0;
                        src_ready <= 1'b1;
                        stage <= S_RUN;
                        started_seen <= 1'b1;
                    end
                end
                S_RUN: begin
                    busy_r <= 1'b1;
                    src_q <= src_q + 8'd1;
                    if (src_q == 8'hFF) begin
                        result <= opnd_q ^ src_q;
                        stage <= S_FIN;
