                    if (ret_valid) begin
                        stage <= S_IDLE;
                        armed_seen <= 1'b0;
                        started_seen <= 1'b0;
                    end
                end
                default: begin
                    stage <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk) busy <= busy_r;

    always @(posedge clk)
        if (pv && stage == 2'd3)
            assert ($past(started_seen));
