    // latency-config window
    always @(posedge clk) begin
        if (en) begin
            if (cfg_unlock)    win <= 1'b0;
            else if (cfg_lock) win <= 1'b1;
        end
    end

    // burst engine
    always @(posedge clk) begin
        if (en) begin
            case (mode)
                2'd0: begin
                    if (rd_req) begin
                        mode   <= 2'd1;
                        own_rd <= 1'b1;
                        cnt    <= len;
                        addr_q <= 3'd0;
                    end else if (wr_req) begin
                        mode   <= 2'd2;
                        own_wr <= 1'b1;
                        cnt    <= len;
                        addr_q <= 3'd0;
                    end
                end
                2'd1: begin
                    data_q <= mem[addr_q];
                    addr_q <= addr_q + 3'd1;
                    cnt    <= cnt - 32'd1;
                    if (cnt == 32'd1) begin
                        mode   <= 2'd0;
                        own_rd <= 1'b0;
                    end
                end
                2'd2: begin
                    mem[addr_q] <= wdata;
                    data_q      <= wdata;
                    addr_q      <= addr_q + 3'd1;
                    cnt         <= cnt - 32'd1;
                    if (cnt == 32'd1) begin
                        mode   <= 2'd0;
                        own_wr <= 1'b0;
                    end
                end
                default: begin
                    mode <= mode;
                end
            endcase
        end
    end

    // absence of dual ownership inside the config window
    always @(posedge clk)
        if (win)
            assert (!(own_rd && own_wr));
endmodule

