reg f_past_valid = 1'b0;
always @(posedge clk) f_past_valid <= 1'b1;

// A master error response cannot be followed immediately by an acknowledgement.
always @(posedge clk) begin
    if (f_past_valid)
        assert (!$past(wbm_err_o) || !wbm_ack_o);
end
