integer f_init_port;
initial begin
    for (f_init_port = 0; f_init_port < PORTS; f_init_port = f_init_port + 1) begin
        port_seg_offset_reg[f_init_port] = 0;
        in_tlp_data_reg[f_init_port] = 0;
        in_tlp_strb_reg[f_init_port] = 0;
        in_tlp_hdr_reg[f_init_port] = 0;
        in_tlp_seq_reg[f_init_port] = 0;
        in_tlp_bar_id_reg[f_init_port] = 0;
        in_tlp_func_num_reg[f_init_port] = 0;
        in_tlp_error_reg[f_init_port] = 0;
        in_tlp_valid_reg[f_init_port] = 0;
        in_tlp_sop_reg[f_init_port] = 0;
        in_tlp_eop_reg[f_init_port] = 0;
    end
end
reg f_past_valid = 1'b0;
always @(posedge clk)
    f_past_valid <= 1'b1;

// Output validity cannot appear from an empty output unless an internal
// valid transfer occurred on the preceding edge.
always @(posedge clk) begin
    if (f_past_valid)
        assert (!(|out_tlp_valid) ||
                $past((|out_tlp_valid) ||
                      (out_tlp_ready_int_reg && (|out_tlp_valid_int))));
