  w_mem[0]  = 32'h0;
  w_mem[1]  = 32'h0;
  w_mem[2]  = 32'h0;
  w_mem[3]  = 32'h0;
  w_mem[4]  = 32'h0;
  w_mem[5]  = 32'h0;
  w_mem[6]  = 32'h0;
  w_mem[7]  = 32'h0;
  w_mem[8]  = 32'h0;
  w_mem[9]  = 32'h0;
  w_mem[10] = 32'h0;
  w_mem[11] = 32'h0;
  w_mem[12] = 32'h0;
  w_mem[13] = 32'h0;
  w_mem[14] = 32'h0;
  w_mem[15] = 32'h0;
end
// Checker-only history bit: some clock edge has sampled init high.
// It intentionally remains set across resets and adds no asynchronous FF.
reg f_seen_init;
initial f_seen_init = 1'b0;
always @(posedge clk) begin
  if (init)
    f_seen_init <= 1'b1;
end

// Before any initialization request has been sampled, word zero is zero.
always @(posedge clk) begin
  assert (f_seen_init || (w_mem[0] == 32'h0));
end
