    .outport_rresp_i(outport_rresp_i),
    .outport_rid_i(outport_rid_i),
    .outport_rlast_i(outport_rlast_i)
);

initial begin
    req_cnt_q = 8'd0;
    resp_outstanding_q = 2'd0;
end
reg f_past_valid;
initial f_past_valid = 1'b0;
always @(posedge clk_i or posedge rst_i)
    if (rst_i)
        f_past_valid <= 1'b0;
    else
